	assign out = ^(stage0);
endmodule

module rtcl_p3s7_blinking_led
        #(
            parameter   int COUNT_LIMIT = 50_000_000
        )
        (
            input   var logic           clk50   ,
            input   var logic           clk72   ,
            output  var logic   [1:0]   led     ,
            output  var logic   [7:0]   pmod    
        );
logic   [31:0]  cnt50   ;
    logic   [31:0]  cnt72   ;

    always_ff @(posedge clk50)
    begin
        cnt50 <= cnt50 + 1;
        led[0]  <= cnt50[31];
        led[1]  <= cnt50[30];
    end

    always_ff @(posedge clk72)
    begin
        cnt72 <= cnt72 + 1;
        pmod[7:0] <= cnt72[31:24];
    end

endmodule

