module 	UART2(
	input  wire	     ipClk,
	input  wire		 ipReset,
	input  wire[7:0]ipTxData,
	input  wire		 ipTxSend,
	output reg 	     opTxBusy,
	output reg       opTx,
	input  wire      ipRx,
	output reg [7:0]opRxData,
	output reg		 opRxValid
);
reg [1:0]TxState;
reg [1:0]RxState;
reg [9:0]TxBdCount;
reg [9:0]RxBdCount;
reg [7:0]RxData;
reg [3:0]RxBitCount;
always@(posedge ipClk or posedge ipReset)
begin
	if(ipReset)
	begin
		TxState <= 2'b00;
		TxBdCount <= 10'd0;
		opTxBusy <= 1'b0;
		opTx <= 1'b0;
	end
	else
	begin
		case(TxState)
			2'b00: begin
				if(ipTxSend)
				begin
					TxState <= 2'b01;
					TxBdCount <= 10'd0;
					opTxBusy <= 1'b1;
					opTx <= 1'b0;
				end
			end
			2'b01: begin
				if(TxBdCount == 10'd433)
				begin
					TxBdCount <= 10'd0;
					opTx <= ipTxData[7];
				end
				else
				begin
					TxBdCount <= TxBdCount + 10'd1;
				end
			end
			2'b10: begin
				if(TxBdCount == 10'd433)
				begin
					TxBdCount <= 10'd0;
					opTx <= 1'b1;
					TxState <= 2'b11;
				end
				else
				begin
					TxBdCount <= TxBdCount + 10'd1;
				end
			end
			2'b11: begin
				TxState <= 2'b00;
				opTxBusy <= 1'b0;
			end
		endcase
	end
end
always@(posedge ipClk or posedge ipReset)
begin
	if(ipReset)
	begin
		RxState <= 2'b00;
		RxBdCount <= 10'd0;
		RxBitCount <= 4'd0;
		opRxValid <= 1'b0;
		opRxData <= 8'd0;
	end
	else
	begin
		case(RxState)
			2'b00: begin
				if(ipRx == 1'b0)
				begin
					RxState <= 2'b01;
					RxBdCount <= 10'd0;
					RxBitCount <= 4'd0;
				end
			end
			2'b01: begin
				if(RxBdCount == 10'd433)
				begin
					RxBdCount <= 10'd0;
					RxData[RxBitCount] <= ipRx;
					RxBitCount <= RxBitCount + 4'd1;
					if(RxBitCount == 4'd7)
					begin
						RxState <= 2'b10;
					end
				end
				else
				begin
					RxBdCount <= RxBdCount + 10'd1;
				end
			end
			2'b10: begin
				if(RxBdCount == 10'd433)
				begin
					RxBdCount <= 10'd0;
					RxState <= 2'b11;
				end
				else
				begin
					RxBdCount <= RxBdCount + 10'd1;
				end
			end
			2'b11: begin
				RxState <= 2'b00;
				opRxValid <= 1'b1;
				opRxData <= RxData;
			end
		endcase
	end
end
endmodule

