input wire pixel_clk,
output wire hsync,
output wire vsync,
output wire [9:0] pixel_x,
output wire [9:0] pixel_y,
output wire visible_region
); 

parameter [31:0] total_pixels=640;
parameter [31:0] hsync_pixels=96;
parameter [31:0] hblank_pixels=160;
parameter [31:0] total_lines=480;
parameter [31:0] vsync_lines=2;
parameter [31:0] vblank_lines=31;
  reg [9:0] hcounter = 0;
  reg [9:0] vcounter = 0;
  reg hsync_reg = 1'b0;
  reg vsync_reg = 1'b0;
  assign hsync = hsync_reg;
  assign vsync = vsync_reg;
  assign pixel_x = hcounter;
  assign pixel_y = vcounter;
  assign visible_region = (hcounter < 640) && (vcounter < 480) ? 1'b1 : 1'b0;
  always @(posedge pixel_clk) begin
    if((hcounter == (total_pixels - 1))) begin
      hcounter <= 0;
      hsync_reg <= 1'b1;
    end
    else begin
      hcounter <= hcounter + 1;
      hsync_reg <= 1'b0;
    end
    if((vcounter == (total_lines - 1))) begin
      vcounter <= 0;
      vsync_reg <= 1'b1;
    end
    else begin
      vcounter <= vcounter + 1;
      vsync_reg <= 1'b0;
    end
  end
endmodule

