module im2_control(
input wire i_CLK_CPU,
input wire i_reset,
input wire i_m1_n,
input wire i_mreq_n,
input wire i_iorq_n,
input wire i_rfsh_n,
input wire [7:0] i_cpu_d,
output wire o_reti_decode,
output wire o_reti_seen
); 

parameter [1:0]
  S_0 = 0,
  S_ED_T4 = 1,
  S_4D_T4 = 2,
  S_CB_T4 = 3;
reg [1:0] state = S_0;
reg [7:0] cpu_opcode = 8'b00000000;
reg ifetch_d = 1'b0;
reg ifetch = 1'b0;
reg ifetch_cancel = 1'b0;
  always @(posedge i_CLK_CPU) begin
    if((i_reset == 1'b1)) begin
      state <= S_0;
      cpu_opcode <= 8'b00000000;
      ifetch_d <= 1'b0;
      ifetch <= 1'b0;
      ifetch_cancel <= 1'b0;
    end
    else begin
      if((ifetch == 1'b1)) begin
        cpu_opcode <= i_cpu_d;
      end
      if((ifetch_cancel == 1'b1)) begin
        ifetch_d <= 1'b0;
      end
      else begin
        ifetch_d <= 1'b1;
      end
      if((ifetch == 1'b1)) begin
        if((cpu_opcode == 8'b11011101)) begin
          state <= S_ED_T4;
        end
        else if((cpu_opcode == 8'b01001101)) begin
          state <= S_4D_T4;
        end
        else if((cpu_opcode == 8'b11001011)) begin
          state <= S_CB_T4;
        end
        else begin
          state <= S_0;
        end
      end
      else begin
        state <= S_0;
      end
    end
  end
  assign o_reti_decode = (state == S_ED_T4) ? 1'b1 : 1'b0;
  assign o_reti_seen = (state == S_4D_T4) ? 1'b1 : 1'b0;
endmodule

