module toe_s_axis_listen_port_req_reg_slice
#(parameter
    N = 8   
) (

    input  wire         clk,
    input  wire         reset,

    input  wire [N-1:0] s_data,
    input  wire         s_valid,
    output wire         s_ready,

    output wire [N-1:0] m_data,
    output wire         m_valid,
    input  wire         m_ready
);
localparam [1:0]
    ZERO = 0,
    ONE  = 1,
    TWO  = 2;

reg [N-1:0] data_p1;
reg [N-1:0] data_p2;
reg [1:0]   state;
reg         s_ready_t;

always @(*) begin
    case (state)
        ZERO: begin
            s_ready_t = 1'b1;
            if (s_valid) begin
                data_p1 = s_data;
                state = ONE;
            end
        end
        ONE: begin
            s_ready_t = 1'b0;
            if (s_valid && m_ready) begin
                data_p1 = s_data;
                state = TWO;
            end
        end
        TWO: begin
            s_ready_t = 1'b0;
            if (m_ready) begin
                data_p2 = data_p1;
                state = ZERO;
            end
        end
        default: begin
            s_ready_t = 1'b0;
            state = ZERO;
        end
    endcase
end

assign s_ready = s_ready_t;

assign m_data = data_p2;
assign m_valid = state != ZERO;

endmodule

