module AXI_WRITE_DATA_CHANNEL_model(
input wire clk,
input wire resetn,
input wire [31:0] data,
input wire go,
output reg done,
output wire [31:0] WDATA,
output reg [3:0] WSTRB,
output reg WVALID,
input wire WREADY
); 

parameter [1:0]
  reset = 0,
  idle = 1,
  running = 2,
  complete = 3;
reg [1:0] current_state; reg [1:0] next_state;
  always @(posedge clk, posedge resetn) begin
    if(resetn == 1'b0) begin
      current_state <= reset;
    end else begin
      current_state <= next_state;
    end
  end
  always @(current_state, go, WREADY) begin
    case(current_state)
    reset : begin
      next_state <= idle;
    end
    idle : begin
      if(go == 1'b1) begin
        next_state <= running;
      end
      else begin
        next_state <= idle;
      end
    end
    running : begin
      if(WREADY == 1'b1) begin
        next_state <= complete;
      end
      else begin
        next_state <= running;
      end
    end
    complete : begin
      next_state <= idle;
    end
    default : begin
      next_state <= reset;
    end
    endcase
  end
  always @(current_state) begin
    case(current_state)
    reset : begin
      WVALID <= 1'b0;
      WSTRB <= 4'b0000;
      WDATA <= 32'b00000000000000000000000000000000;
      done <= 1'b0;
    end
    idle : begin
      WVALID <= 1'b0;
      WSTRB <= 4'b0000;
      WDATA <= 32'b00000000000000000000000000000000;
      done <= 1'b0;
    end
    running : begin
      WVALID <= 1'b1;
      WSTRB <= 4'b1111;
      WDATA <= data;
      done <= 1'b0;
    end
    complete : begin
      WVALID <= 1'b0;
      WSTRB <= 4'b0000;
      WDATA <= 32'b00000000000000000000000000000000;
      done <= 1'b1;
    end
    default : begin
      WVALID <= 1'b0;
      WSTRB <= 4'b0000;
      WDATA <= 32'b00000000000000000000000000000000;
      done <= 1'b0;
    end
    endcase
  end
endmodule

