            if (i_wen) begin
                case (i_addr)
                    16'h0000: r_reg0000 <= i_wdata;
                    16'h0002: r_reg0002 <= i_wdata;
                    16'h0004: r_reg0004 <= i_wdata;
                    16'h0006: r_reg0006 <= i_wdata;
