            end
        end
    end

    always @(*) begin
        case (i_addr)
            16'h0000: o_q = r_reg0000;
            16'h0002: o_q = r_reg0002;
            16'h0004: o_q = r_reg0004;
            16'h0006: o_q = r_reg0006;
            default: o_q = 16'h0000;
        endcase
    end

    assign o_reg0000 = r_reg0000;
