  #(parameter match_data = 0,
    parameter match_mask = 0)
   (input clk, input reset, input clear,
    input [35:0] data_i, input src_rdy_i, output dst_rdy_o,
    output [35:0] data0_o, output src0_rdy_o, input dst0_rdy_i,
    output [35:0] data1_o, output src1_rdy_o, input dst1_rdy_i);
reg [1:0] state;
   localparam IDLE = 0, DATA0 = 1, DATA1 = 2;
   reg eof;
   reg [35:0] data0_o, data1_o;
   reg src0_rdy_o, src1_rdy_o;
   assign dst_rdy_o = (state == DATA0) ? dst0_rdy_i : dst1_rdy_i;
   always @(posedge clk or posedge reset or posedge clear) begin
      if (reset || clear) begin
	 state <= IDLE;
      end else begin
	 case (state)
	    IDLE: begin
	       if (src_rdy_i) begin
		  state <= DATA0;
	       end
	    end
	    DATA0: begin
	       if (eof) begin
		  state <= DATA1;
	       end
	    end
	    DATA1: begin
	       if (eof) begin
		  state <= IDLE;
	       end
	    end
	 endcase
      end
   end
   always @(*) begin
      eof = 0;
      data0_o = 0;
      data1_o = 0;
      src0_rdy_o = 0;
      src1_rdy_o = 0;
