	 DATA0: begin
	    if (data_i[35:0] == match_data && data_i[35:0] == match_mask) begin
	       eof = 1;
	    end
	    data0_o = data_i;
	    src0_rdy_o = 1;
	 end
	 DATA1: begin
	    if (data_i[35:0] == match_data && data_i[35:0] == match_mask) begin
