module jtframe_romrq #(parameter AW=18, DW=8 )(
    input               rst,
    input               clk,
    input               clr, 
    input [21:0]        offset,
    input [AW-1:0]      addr,
    input               addr_ok,    
    input [31:0]        din,
    input               din_ok,
    input               we,
    output reg          req,
    output reg          data_ok,    
    output     [21:0]   sdram_addr,
    output reg [DW-1:0] dout
);
reg [AW-1:0] addr_req;
reg [AW-1:0] cached_addr0;
reg [AW-1:0] cached_addr1;
reg [DW-1:0] cached_data0;
reg [DW-1:0] cached_data1;
reg [1:0] subaddr;
reg good;

always @(*) begin
    case (DW)
        8:  addr_req = {addr[17:0], 2'b00};
        16: addr_req = {addr[17:0], 1'b0};
        32: addr_req = addr;
        default: addr_req = addr;
    endcase
end

reg hit0, hit1;

always @(*) begin
    hit0 = (addr_req == cached_addr0);
    hit1 = (addr_req == cached_addr1);
end

always @(*) begin
    req = 0;
    data_ok = 0;
    sdram_addr = addr_req;
    dout = 0;
    if (addr_ok) begin
        if (hit0 || hit1) begin
            data_ok = 1;
            if (hit0) dout = cached_data0;
            if (hit1) dout = cached_data1;
        end else begin
            req = 1;
            data_ok = 0;
            sdram_addr = addr_req + offset;
        end
    end
end

always @(posedge clk or posedge rst) begin
    if (rst) begin
        good <= 0;
    end else begin
        if (clr) begin
            good <= 0;
        end else begin
            if (we) begin
                if (good) begin
                    if (subaddr == 0) begin
                        cached_addr0 <= addr_req;
                        cached_data0 <= din[DW-1:0];
                    end else begin
                        cached_addr1 <= addr_req;
                        cached_data1 <= din[DW-1:0];
                    end
                end
                good <= 1;
            end else begin
                good <= 0;
            end
        end
    end
end

always @(posedge clk or posedge rst) begin
    if (rst) begin
        subaddr <= 0;
    end else begin
        if (clr) begin
            subaddr <= 0;
        end else begin
            if (addr_ok) begin
                if (good) begin
                    if (hit0) begin
                        subaddr <= 1;
                    end else begin
                        subaddr <= 0;
                    end
                end else begin
                    subaddr <= 0;
                end
            end else begin
                subaddr <= 0;
            end
        end
    end
end

endmodule

