module vga_controller(
input wire RST,
input wire CLK,
output wire H_SYNC,
output wire V_SYNC,
output wire [10:0] X,
output wire [10:0] Y,
output wire DISP_EN
); 

parameter [31:0] H_ACTIVE=1280;
parameter [31:0] H_FRONT_PORCH=160;
parameter [31:0] H_SYNC_PULSE=96;
parameter [31:0] H_BACK_PORCH=48;
parameter [31:0] H_TOTAL=1656;
parameter [31:0] V_ACTIVE=720;
parameter [31:0] V_FRONT_PORCH=20;
parameter [31:0] V_SYNC_PULSE=5;
parameter [31:0] V_BACK_PORCH=45;
parameter [31:0] V_TOTAL=798;
reg [10:0] X = 0;
reg [10:0] Y = 0;
reg H_SYNC = 1;
reg V_SYNC = 1;
reg DISP_EN = 0;
  always @(posedge CLK, posedge RST) begin
    if(RST == 1'b1) begin
      X <= 0;
      Y <= 0;
      H_SYNC <= 1;
      V_SYNC <= 1;
      DISP_EN <= 0;
    end else begin
      if(X == (H_ACTIVE - 1)) begin
        X <= 0;
        if(Y == (V_ACTIVE - 1)) begin
          Y <= 0;
          V_SYNC <= 1;
        end
        else begin
          Y <= Y + 1;
          V_SYNC <= 0;
        end
      end
      else begin
        X <= X + 1;
        V_SYNC <= 0;
      end
      if(X < H_ACTIVE) begin
        DISP_EN <= 1;
      end
      else begin
        DISP_EN <= 0;
      end
      if(X >= (H_ACTIVE + H_FRONT_PORCH)) begin
        H_SYNC <= 1;
      end
      else begin
        H_SYNC <= 0;
      end
      if(X >= (H_ACTIVE + H_FRONT_PORCH + H_SYNC_PULSE)) begin
        H_SYNC <= 1;
      end
      if(X >= (H_ACTIVE + H_FRONT_PORCH + H_SYNC_PULSE + H_BACK_PORCH)) begin
        H_SYNC <= 1;
      end
      if(Y < V_ACTIVE) begin
        DISP_EN <= 1;
      end
      else begin
        DISP_EN <= 0;
      end
      if(Y >= (V_ACTIVE + V_FRONT_PORCH)) begin
        V_SYNC <= 1;
      end
      else begin
        V_SYNC <= 0;
      end
      if(Y >= (V_ACTIVE + V_FRONT_PORCH + V_SYNC_PULSE)) begin
        V_SYNC <= 1;
      end
      if(Y >= (V_ACTIVE + V_FRONT_PORCH + V_SYNC_PULSE + V_BACK_PORCH)) begin
        V_SYNC <= 1;
      end
    end
  end
endmodule

