module ps2controller (
    input reset,
    input i_clock,
    input i_data,
    output scan_ready,
    output [7:0] scan_code
);
reg [7:0] scan_code;
    reg [3:0] counter;
    reg parity;
    reg stop_bit;
    reg [7:0] data_buffer;
    reg [3:0] data_counter;
    reg parity_error;
    reg ready;
    assign scan_ready = ready;
    assign scan_code = data_buffer;
    always @(posedge reset or negedge i_clock) begin
        if (reset) begin
            counter <= 0;
            parity <= 0;
            stop_bit <= 0;
            data_counter <= 0;
            parity_error <= 0;
            ready <= 0;
        end else begin
            if (counter == 0) begin
                if (i_data == 0) begin
                    counter <= 1;
                end
            end else if (counter == 1) begin
                data_buffer[data_counter] <= i_data;
                data_counter <= data_counter + 1;
                if (data_counter == 7) begin
                    parity <= i_data;
                    counter <= 2;
                end
            end else if (counter == 2) begin
                stop_bit <= i_data;
                counter <= 3;
            end else if (counter == 3) begin
                if (stop_bit == 0) begin
                    if (parity == 0) begin
                        parity_error <= 0;
                    end else begin
                        parity_error <= 1;
                    end
                end
                counter <= 0;
                data_counter <= 0;
                ready <= 1;
            end
        end
    end
endmodule

