module toe_m_axis_rxread_cmd_reg_slice
#(parameter
    N = 8   
) (

    input  wire         clk,
    input  wire         reset,

    input  wire [N-1:0] s_data,
    input  wire         s_valid,
    output wire         s_ready,

    output wire [N-1:0] m_data,
    output wire         m_valid,
    input  wire         m_ready
);
localparam [1:0]
    ZERO = 0,
    ONE  = 1,
    TWO  = 2;

reg [N-1:0] data_p1;
reg [N-1:0] data_p2;

reg         load_p1;
reg         load_p2;
reg         load_p1_from_p2;

wire        s_ready_t;
wire        m_valid_t;

assign s_ready = s_ready_t;
assign m_valid = m_valid_t;
assign m_data  = data_p2;

assign s_ready_t = (load_p1) ? 1'b1 : 1'b0;
assign m_valid_t = (load_p2) ? 1'b1 : 1'b0;

reg [1:0] state;
reg [1:0] next_state;

always @(posedge clk) begin
    if (reset == 1'b1) begin
        state <= ZERO;
    end else begin
        state <= next_state;
    end
end

always @(*) begin
    case (state)
        ZERO: begin
            if (s_valid == 1'b1 && m_ready == 1'b1) begin
                next_state = ONE;
            end else begin
                next_state = ZERO;
            end
        end
        ONE: begin
            if (s_valid == 1'b0 && m_ready == 1'b0) begin
                next_state = ZERO;
            end else if (s_valid == 1'b1 && m_ready == 1'b1) begin
                next_state = TWO;
            end else begin
                next_state = ONE;
            end
        end
        TWO: begin
            if (s_valid == 1'b0 && m_ready == 1'b1) begin
                next_state = ONE;
            end else begin
                next_state = TWO;
            end
        end
        default: begin
            next_state = ZERO;
        end
    endcase
end

always @(posedge clk) begin
    if (reset == 1'b1) begin
        load_p1 <= 1'b0;
        load_p2 <= 1'b0;
        load_p1_from_p2 <= 1'b0;
    end else begin
        load_p1 <= load_p1_from_p2;
        load_p2 <= load_p1;
        load_p1_from_p2 <= 1'b0;
    end
end

always @(posedge clk) begin
    if (reset == 1'b1) begin
        data_p1 <= {N{1'b0}};
        data_p2 <= {N{1'b0}};
    end else begin
        if (load_p1 == 1'b1) begin
            data_p1 <= s_data;
        end
        if (load_p1_from_p2 == 1'b1) begin
            data_p1 <= data_p2;
        end
        if (load_p2 == 1'b1) begin
            data_p2 <= data_p1;
        end
    end
end

always @(*) begin
    case (state)
        ZERO: begin
            load_p1_from_p2 = 1'b0;
        end
        ONE: begin
            if (s_valid == 1'b1 && m_ready == 1'b1) begin
                load_p1_from_p2 = 1'b1;
            end else begin
                load_p1_from_p2 = 1'b0;
            end
        end
        TWO: begin
            load_p1_from_p2 = 1'b1;
        end
        default: begin
            load_p1_from_p2 = 1'b0;
        end
    endcase
end

endmodule

