	   4'b0110: alu_result_int = alu_src1 >> alu_src2;
	   4'b0111: alu_result_int = alu_src1 >>> alu_src2;
	   default: alu_result_int = 32'h00000000;
	endcase
	alu_result = alu_result_int[31:0];
	minus_is_zero = (alu_result_int[31:0] == 32'h00000000) ? 1'b1 : 1'b0;
	less_than = (alu_result_int[31:0] < 32'h00000000) ? 1'b1 : 1'b0;
