always @(posedge clk or posedge aclr) begin
    if (aclr)
        empty <= 1;
    else if (read && ~empty)
        empty <= 1'b0;
    else if (write && ~full)
        empty <= 1'b1;
end

always @(posedge clk or posedge aclr) begin
    if (aclr)
        full <= 0;
    else if (write && ~full)
        full <= 1'b0;
    else if (read && ~empty)
        full <= 1'b1;
end

