	parameter MAX = 2**WIDTH - 1;
	wire [2:0] uds;
	assign uds = {up, down, set};
	initial begin
		out = 0;
	end
	always @(posedge clk) begin
		if (uds[2]) begin
			out <= in;
		end else if (uds[1]) begin
			if (out == MAX) begin
				out <= out;
			end else begin
				out <= out + 1;
			end
		end else if (uds[0]) begin
			if (out == 0) begin
				out <= out;
			end else begin
				out <= out - 1;
			end
		end else begin
			out <= out;
		end
	end
endmodule

