module multpool_rdata_mux #(
  parameter NBITS     = 256,
  parameter NUM_RDATA = 1024) (
  input  wire               hclk,     
  input  wire               hresetn,  
  input  wire [3*NBITS-1:0] rdata [0 :NUM_RDATA-1],
  input  wire               valid_rd,
  output wire [3*NBITS-1:0] hrdata
);
reg [NBITS-1:0] rdata0 [0 :NUM_RDATA/4-1];
  reg [NBITS-1:0] rdata1 [0 :NUM_RDATA/4-1];
  reg [NBITS-1:0] rdata2 [0 :NUM_RDATA/4-1];
  reg [NBITS-1:0] rdata3 [0 :NUM_RDATA/4-1];
  reg [NBITS-1:0] hrdata_int [0 :NUM_RDATA/4-1];
  integer i;

  always @(posedge hclk or negedge hresetn) begin
    if (!hresetn) begin
      for (i = 0; i < NUM_RDATA/4; i = i + 1) begin
        rdata0[i] <= 0;
        rdata1[i] <= 0;
        rdata2[i] <= 0;
        rdata3[i] <= 0;
      end
    end else if (valid_rd) begin
      for (i = 0; i < NUM_RDATA/4; i = i + 1) begin
        rdata0[i] <= rdata[i];
        rdata1[i] <= rdata[i+NUM_RDATA/4];
        rdata2[i] <= rdata[i+2*NUM_RDATA/4];
        rdata3[i] <= rdata[i+3*NUM_RDATA/4];
      end
    end
  end

  always @(*) begin
    for (i = 0; i < NUM_RDATA/4; i = i + 1) begin
      hrdata_int[i] = 0;
      hrdata_int[i] = hrdata_int[i] | rdata0[i];
      hrdata_int[i] = hrdata_int[i] | rdata1[i];
      hrdata_int[i] = hrdata_int[i] | rdata2[i];
      hrdata_int[i] = hrdata_int[i] | rdata3[i];
    end
  end

  assign hrdata = {hrdata_int[0], hrdata_int[1], hrdata_int[2], hrdata_int[3]};

endmodule

