module udpLoopback_lbRxMetadataIn_reg_slice
#(parameter
    N = 8   
) (

    input  wire         clk,
    input  wire         reset,

    input  wire [N-1:0] s_data,
    input  wire         s_valid,
    output wire         s_ready,

    output wire [N-1:0] m_data,
    output wire         m_valid,
    input  wire         m_ready
);
localparam [1:0]
    ZERO = 0,
    ONE  = 1,
    TWO  = 2;

reg [N-1:0] data_p1;
reg [N-1:0] data_p2;
reg [1:0]   state;
reg         load_p1;
reg         load_p2;

wire        load_p1_in  = s_valid & s_ready & ~state[0];
wire        load_p2_in  = state[1] & ~state[0];
wire        load_p1_out = state[0] & ~state[1];
wire        load_p2_out = state[1] & state[0];

assign m_data  = data_p1;
assign m_valid = state[1];
assign s_ready = state[0];

always @(posedge clk) begin
    if (load_p1) begin
        data_p1 <= s_data;
    end
end

always @(posedge clk) begin
    if (load_p2) begin
        data_p2 <= data_p1;
    end
end

always @(posedge clk) begin
    case (state)
        ZERO: begin
            if (load_p1_in) begin
                state <= ONE;
            end
        end
        ONE: begin
            if (load_p1_out) begin
                state <= ZERO;
            end else if (load_p2_in) begin
                state <= TWO;
            end
        end
        TWO: begin
            if (load_p2_out) begin
                state <= ONE;
            end
        end
    endcase
end

always @(*) begin
    load_p1 = 1'b0;
    load_p2 = 1'b0;
    case (state)
        ZERO: begin
            load_p1 = load_p1_in;
        end
        ONE: begin
            load_p1 = load_p1_out;
            load_p2 = load_p2_in;
        end
        TWO: begin
            load_p2 = load_p2_out;
        end
    endcase
end

endmodule

