module blake2_G(
                input wire [63 : 0]  a,
                input wire [63 : 0]  b,
                input wire [63 : 0]  c,
                input wire [63 : 0]  d,
                input wire [63 : 0]  m0,
                input wire [63 : 0]  m1,

                output wire [63 : 0] a_prim,
                output wire [63 : 0] b_prim,
                output wire [63 : 0] c_prim,
                output wire [63 : 0] d_prim
               );
reg [63 : 0] a0, a1, b0, b1, b2, b3, c0, c1, d0, d1, d2, d3;

always @* begin
    a0 = a + b;
    a1 = a0 ^ c;
    a0 = a0 + d;
    a1 = a1 + m0;
    a0 = a0 + m1;
    a1 = a1 + a0;
    a0 = a0 + a1;
    a1 = a1 + a0;

    b0 = b + c;
    b1 = b0 ^ d;
    b0 = b0 + a;
    b1 = b1 + m0;
    b0 = b0 + m1;
    b1 = b1 + b0;
    b0 = b0 + b1;
    b1 = b1 + b0;

    c0 = c + d;
    c1 = c0 ^ a;
    c0 = c0 + b;
    c1 = c1 + m0;
    c0 = c0 + m1;
    c1 = c1 + c0;
    c0 = c0 + c1;
    c1 = c1 + c0;

    d0 = d + a;
    d1 = d0 ^ b;
    d0 = d0 + c;
    d1 = d1 + m0;
    d0 = d0 + m1;
    d1 = d1 + d0;
    d0 = d0 + d1;
    d1 = d1 + d0;
end

assign a_prim = a0 + a1;
assign b_prim = b0 + b1;
assign c_prim = c0 + c1;
assign d_prim = d0 + d1;

endmodule

