module complexmulttrial(
input [15:0] a_r,
input [15:0] a_i,
input [15:0] b_r,
input [15:0] b_i,
input [15:0] w_r,
input [15:0] w_i,
output [15:0] x_r,
output [15:0] x_i,
output [15:0] y_r,
output [15:0] y_i);
wire [31:0] x_r_int;
wire [31:0] x_i_int;
wire [31:0] y_r_int;
wire [31:0] y_i_int;

assign x_r_int = a_r + b_r;
assign x_i_int = a_i + b_i;
assign y_r_int = (a_r - b_r) * w_r - (a_i - b_i) * w_i;
assign y_i_int = (a_r - b_r) * w_i + (a_i - b_i) * w_r;

assign x_r = x_r_int[31:16];
assign x_i = x_i_int[31:16];
assign y_r = y_r_int[31:16];
assign y_i = y_i_int[31:16];

endmodule

