module shift #(
    parameter DATA_WIDTH = 16,
    parameter DATA_TYPE = "unsigned", 
    parameter SHIFT_VALUE = 1,      
    parameter ASYNC = 0,             
    parameter OVERFLOW_WARNING = 1
) (
    input wire clk,
    input wire [DATA_WIDTH-1:0] din,

    output wire [DATA_WIDTH-1:0] dout,
    output wire [1:0] warning
);
generate
    if (DATA_TYPE == "signed") begin
        reg [DATA_WIDTH-1:0] dout_reg;
        reg [1:0] warning_reg;

        if (ASYNC == 0) begin
            always @(posedge clk) begin
                dout_reg <= din << SHIFT_VALUE;
                if (OVERFLOW_WARNING == 1) begin
                    if (din[DATA_WIDTH-1] == 0 && din[DATA_WIDTH-1-:DATA_WIDTH-1] >= 2**(DATA_WIDTH-2-:DATA_WIDTH-2)) begin
                        warning_reg <= 2'b01;
                    end else if (din[DATA_WIDTH-1] == 1 && din[DATA_WIDTH-1-:DATA_WIDTH-1] >= 2**(DATA_WIDTH-2-:DATA_WIDTH-2)) begin
                        warning_reg <= 2'b10;
                    end else begin
                        warning_reg <= 2'b00;
                    end
                end
            end
        end else begin
            assign dout = din << SHIFT_VALUE;
            if (OVERFLOW_WARNING == 1) begin
                if (din[DATA_WIDTH-1] == 0 && din[DATA_WIDTH-1-:DATA_WIDTH-1] >= 2**(DATA_WIDTH-2-:DATA_WIDTH-2)) begin
                    assign warning = 2'b01;
                end else if (din[DATA_WIDTH-1] == 1 && din[DATA_WIDTH-1-:DATA_WIDTH-1] >= 2**(DATA_WIDTH-2-:DATA_WIDTH-2)) begin
                    assign warning = 2'b10;
                end else begin
                    assign warning = 2'b00;
                end
            end
        end

        assign dout = dout_reg;
        assign warning = warning_reg;
    end else begin
        reg [DATA_WIDTH-1:0] dout_reg;
        reg [1:0] warning_reg;

        if (ASYNC == 0) begin
            always @(posedge clk) begin
                dout_reg <= din >> SHIFT_VALUE;
                if (OVERFLOW_WARNING == 1) begin
                    if (din >= 2**(DATA_WIDTH-1)) begin
                        warning_reg <= 2'b01;
                    end else begin
                        warning_reg <= 2'b00;
                    end
                end
            end
        end else begin
            assign dout = din >> SHIFT_VALUE;
            if (OVERFLOW_WARNING == 1) begin
                if (din >= 2**(DATA_WIDTH-1)) begin
                    assign warning = 2'b01;
                end else begin
                    assign warning = 2'b00;
                end
            end
        end

        assign dout = dout_reg;
        assign warning = warning_reg;
    end
endgenerate

endmodule

