module alu_32 (
  input_a,
  input_b,
  control,
  zero, 
  cout,
  err_overflow,
  err_invalid_control,
  result
); 

input wire [WORD_SIZE-1:0]	input_a;
input wire [WORD_SIZE-1:0]	input_b;
input wire [CONTROL_SIGNAL_SIZE-1:0]	control;
output wire       zero;
output reg	      cout;
output reg	      err_overflow;
output reg	      err_invalid_control;
output reg [WORD_SIZE-1:0]	result;
parameter WORD_SIZE = 32;
parameter CONTROL_SIGNAL_SIZE = 4;

parameter AND = 4'b0000;
parameter OR = 4'b0001;
parameter ADD = 4'b0010;
parameter ADD_UNSIGNED = 4'b0011;
parameter SUB = 4'b0100;
parameter SLT = 4'b0101;
parameter NOR = 4'b0110;

parameter ERR_OVERFLOW = 1'b1;
parameter ERR_INVALID_CONTROL = 1'b1;

reg [WORD_SIZE-1:0]	result_int;
reg [WORD_SIZE-1:0]	result_int_signed;
reg [WORD_SIZE-1:0]	result_int_unsigned;
reg [WORD_SIZE-1:0]	result_int_signed_sub;
reg [WORD_SIZE-1:0]	result_int_unsigned_sub;
reg [WORD_SIZE-1:0]	result_int_signed_add;
reg [WORD_SIZE-1:0]	result_int_unsigned_add;
reg [WORD_SIZE-1:0]	result_int_signed_add_unsigned;
reg [WORD_SIZE-1:0]	result_int_unsigned_add_signed;
reg [WORD_SIZE-1:0]	result_int_signed_sub_unsigned;
reg [WORD_SIZE-1:0]	result_int_unsigned_sub_signed;
reg [WORD_SIZE-1:0]	result_int_signed_add_signed;
reg [WORD_SIZE-1:0]	result_int_unsigned_add_unsigned;

always @(*) begin
  case (control)
    AND: begin
      result_int = input_a & input_b;
      cout = 1'b0;
      err_overflow = 1'b0;
      err_invalid_control = 1'b0;
    end
    OR: begin
      result_int = input_a | input_b;
      cout = 1'b0;
      err_overflow = 1'b0;
      err_invalid_control = 1'b0;
    end
    ADD: begin
      result_int_signed = $signed(input_a) + $signed(input_b);
      result_int = result_int_signed;
      cout = result_int_signed[WORD_SIZE-1];
      err_overflow = (result_int_signed[WORD_SIZE-1] != result_int_signed[WORD_SIZE-2]);
      err_invalid_control = 1'b0;
    end
    ADD_UNSIGNED: begin
      result_int_unsigned = input_a + input_b;
      result_int = result_int_unsigned;
      cout = result_int_unsigned[WORD_SIZE-1];
      err_overflow = 1'b0;
      err_invalid_control = 1'b0;
    end
    SUB: begin
      result_int_signed_sub = $signed(input_a) - $signed(input_b);
      result_int = result_int_signed_sub;
      cout = result_int_signed_sub[WORD_SIZE-1];
      err_overflow = (result_int_signed_sub[WORD_SIZE-1] != result_int_signed_sub[WORD_SIZE-2]);
      err_invalid_control = 1'b0;
    end
    SLT: begin
      result_int_signed = $signed(input_a) < $signed(input_b);
      result_int = result_int_signed;
      cout = 1'b0;
      err_overflow = 1'b0;
      err_invalid_control = 1'b0;
    end
    NOR: begin
      result_int = ~(input_a | input_b);
      cout = 1'b0;
      err_overflow = 1'b0;
      err_invalid_control = 1'b0;
    end
    default: begin
      result_int = 32'b0;
      cout = 1'b0;
      err_overflow = 1'b0;
      err_invalid_control = ERR_INVALID_CONTROL;
    end
  endcase
end

assign zero = (result_int == 32'b0);
assign result = result_int;

endmodule

