module pwm#(
	    parameter WAVE_WEIGHT=1024, 
	    parameter WAVE_LEN_WIDTH = 11 
	    )
    (
     input wire clk,
     input wire reset,


     input wire update,
     input wire [WAVE_LEN_WIDTH-1:0] wave_length,
     input wire [WAVE_LEN_WIDTH-1:0] pulse_width,
     input wire active_high,

     output wire [WAVE_LEN_WIDTH-1:0] wave_length_out,
     output wire [WAVE_LEN_WIDTH-1:0] pulse_width_out,
     output wire active_high_out,

     input wire enable,
     output wire pwm_out
     );
reg [WAVE_LEN_WIDTH-1:0] wave_length_out_reg;
    reg [WAVE_LEN_WIDTH-1:0] pulse_width_out_reg;
    reg active_high_out_reg;

    reg [WAVE_LEN_WIDTH-1:0] wave_length_reg;
    reg [WAVE_LEN_WIDTH-1:0] pulse_width_reg;
    reg active_high_reg;

    reg [WAVE_LEN_WIDTH-1:0] weight_reg;
    reg [WAVE_LEN_WIDTH-1:0] wave_length_reg;

    reg pwm_out_reg;

    always @(posedge clk or posedge reset)
      begin
	if (reset)
	  begin
	      wave_length_out_reg <= 0;
	      pulse_width_out_reg <= 0;
	      active_high_out_reg <= 0;
	      wave_length_reg <= 0;
	      pulse_width_reg <= 0;
	      active_high_reg <= 0;
	      weight_reg <= 0;
	      wave_length_reg <= 0;
	      pwm_out_reg <= 0;
	  end
	else
	  begin
	      if (update)
		begin
		    wave_length_reg <= wave_length;
		    pulse_width_reg <= pulse_width;
		    active_high_reg <= active_high;
		end
	      wave_length_out_reg <= wave_length_reg;
	      pulse_width_out_reg <= pulse_width_reg;
	      active_high_out_reg <= active_high_reg;
	      if (weight_reg < pulse_width_reg)
		begin
		    pwm_out_reg <= active_high_reg;
		end
	      else
		begin
		    pwm_out_reg <= ~active_high_reg;
		end
	      if (weight_reg < WAVE_WEIGHT)
		begin
		    weight_reg <= weight_reg + 1;
		end
	      else
		begin
		    weight_reg <= 0;
		end
	  end
      end

    assign wave_length_out = wave_length_out_reg;
    assign pulse_width_out = pulse_width_out_reg;
    assign active_high_out = active_high_out_reg;
    assign pwm_out = pwm_out_reg;

endmodule

