module scan_hex_led_disp(
    input clk,reset,
    input [3:0] hex3,hex2,hex1,hex0,
    input [3:0] dp,
    output reg[3:0] en, 
    output reg[7:0] sseg
    );
reg [1:0] cnt;
    always@(posedge clk or posedge reset)
    begin
        if(reset)
            cnt<=2'b00;
        else
            cnt<=cnt+1;
    end
    always@(cnt)
    begin
        case(cnt)
            2'b00:begin
                en<=4'b1110;
                sseg<=hex0;
            end
            2'b01:begin
                en<=4'b1101;
                sseg<=hex1;
            end
            2'b10:begin
                en<=4'b1011;
                sseg<=hex2;
            end
            2'b11:begin
                en<=4'b0111;
                sseg<=hex3;
            end
        endcase
    end
    always@(sseg)
    begin
        case(sseg)
            4'h0:sseg<=7'b1000000;
            4'h1:sseg<=7'b1111001;
            4'h2:sseg<=7'b0100100;
            4'h3:sseg<=7'b0110000;
            4'h4:sseg<=7'b0011001;
            4'h5:sseg<=7'b0010010;
            4'h6:sseg<=7'b0000010;
            4'h7:sseg<=7'b1111000;
            4'h8:sseg<=7'b0000000;
            4'h9:sseg<=7'b0010000;
            4'hA:sseg<=7'b0001000;
            4'hB:sseg<=7'b0000011;
            4'hC:sseg<=7'b1000110;
            4'hD:sseg<=7'b0100001;
            4'hE:sseg<=7'b0000110;
            4'hF:sseg<=7'b0001110;
        endcase
    end
    always@(dp)
    begin
        case(dp)
            4'h0:sseg[7]<=1'b0;
            4'h1:sseg[7]<=1'b1;
            4'h2:sseg[7]<=1'b0;
            4'h3:sseg[7]<=1'b1;
            4'h4:sseg[7]<=1'b0;
            4'h5:sseg[7]<=1'b1;
            4'h6:sseg[7]<=1'b0;
            4'h7:sseg[7]<=1'b1;
        endcase
    end
