module binary_updown_counter #(parameter BITS = 1)
        (input wire clk, input wire rst, input wire ena,
         input wire updown, output wire [BITS - 1:0] out, output wire ovf);
reg [BITS - 1:0] cnt;
    wire [BITS - 1:0] enable_wires;
    assign enable_wires[0] = ena;
    genvar i;
    generate
        for (i = 0; i < BITS; i = i + 1) begin : gen_counter
            always @(posedge clk or posedge rst) begin
                if (rst) begin
                    cnt[i] <= 0;
                end else begin
                    if (enable_wires[i]) begin
                        if (updown) begin
                            cnt[i] <= cnt[i] + 1;
                        end else begin
                            cnt[i] <= cnt[i] - 1;
                        end
                    end
                end
            end
            assign enable_wires[i + 1] = enable_wires[i] & (cnt[i] == 0);
        end
    endgenerate
    assign out = cnt;
    assign ovf = (cnt == 0) & ena;
endmodule

