module IB_ENDPOINT_OP_DONE_BUFFER(
input wire CLK,
input wire RESET,
input wire [15:0] RD_COMPL_TAG,
input wire RD_COMPL_START,
input wire RD_COMPL_DONE,
input wire [15:0] BM_TAG,
input wire BM_DONE,
output wire [15:0] OP_TAG,
output wire OP_DONE
); 

reg [15:0] rd_compl_tag_reg = 1'b0;
reg rd_compl_start_reg = 1'b0;
reg rd_compl_done_reg = 1'b0;
reg bm_tag_valid_reg = 1'b0;
  always @(posedge CLK, posedge RESET) begin
    if((RESET == 1'b1)) begin
      rd_compl_tag_reg <= {16{1'b0}};
      rd_compl_start_reg <= 1'b0;
      rd_compl_done_reg <= 1'b0;
      bm_tag_valid_reg <= 1'b0;
    end else begin
      rd_compl_tag_reg <= RD_COMPL_TAG;
      rd_compl_start_reg <= RD_COMPL_START;
      rd_compl_done_reg <= RD_COMPL_DONE;
      bm_tag_valid_reg <= BM_DONE;
    end
  end
  assign OP_TAG = rd_compl_start_reg == 1'b1 ? rd_compl_tag_reg : BM_TAG;
  assign OP_DONE = rd_compl_done_reg | bm_tag_valid_reg;
endmodule

