module stratixiii_bias_logic (
    clk,
    shiftnld,
    captnupdt,
    mainclk,
    updateclk,
    capture,
    update
    );


input  clk;
input  shiftnld;
input  captnupdt;


output mainclk;
output updateclk;
output capture;
output update;
reg tmp_mainclk;
reg tmp_updateclk;
reg tmp_capture;
reg tmp_update;

and (mainclk, tmp_mainclk, 1'b1);
and (updateclk, tmp_updateclk, 1'b1);
and (capture, tmp_capture, 1'b1);
and (update, tmp_update, 1'b1);

initial
begin
    tmp_mainclk <= 1'b0;
    tmp_updateclk <= 1'b0;
    tmp_capture <= 1'b0;
    tmp_update <= 1'b0;
end

always @(captnupdt or shiftnld or clk)
begin
    case ({captnupdt, shiftnld})
        2'b10, 2'b11:
        begin
            tmp_mainclk <= 1'b0;
            tmp_updateclk <= 1'b0;
            tmp_capture <= 1'b1;
            tmp_update <= 1'b0;
        end
        2'b01:
        begin
            tmp_mainclk <= 1'b0;
            tmp_updateclk <= clk;
            tmp_capture <= 1'b0;
            tmp_update <= 1'b0;
        end
        default:
        begin
            tmp_mainclk <= clk;
            tmp_updateclk <= 1'b0;
            tmp_capture <= 1'b0;
            tmp_update <= 1'b1;
        end
    endcase
end

endmodule

