reg [31:0] sigma = 0;
reg [31:0] undersampled_sigma = 0;
reg [31:0] delta = 0;
reg [31:0] deriv = 0;

always @(posedge clk or negedge rstn) begin
	if (!rstn) begin
		sigma <= 0;
		undersampled_sigma <= 0;
	end else begin
		if (ock) begin
			if (sdi) begin
				sigma <= sigma + 1;
			end else begin
				sigma <= sigma - 1;
			end
		end
		if (uck) begin
			undersampled_sigma <= sigma;
		end
	end
end

always @(posedge clk or negedge rstn) begin
	if (!rstn) begin
		delta <= 0;
		deriv <= 0;
	end else begin
		if (ock) begin
			delta <= sigma - undersampled_sigma;
		end
		if (uck) begin
			deriv <= delta;
		end
	end
end

assign dout = signed_data ? $signed(deriv) : deriv;

endmodule

