module adapter_rgb_2_ppfifo #(
  parameter                 DATA_WIDTH = 24
)(
  input                             clk,
  input                             rst,

  input         [23:0]              i_rgb,
  input                             i_h_sync,
  input                             i_h_blank,
  input                             i_v_sync,
  input                             i_v_blank,
  input                             i_data_en,


  output                            o_ppfifo_clk,
  input       [1:0]                 i_ppfifo_rdy,
  output  reg [1:0]                 o_ppfifo_act,
  input       [23:0]                i_ppfifo_size,
  output  reg                       o_ppfifo_stb,
  output  reg [DATA_WIDTH - 1:0]    o_ppfifo_data


);
reg [31:0] r_count;
  reg [1:0] state;
  localparam IDLE = 0;
  localparam READY = 1;
  localparam RELEASE = 2;

  always @(posedge clk or posedge rst) begin
    if (rst) begin
      r_count <= 0;
      state <= IDLE;
      o_ppfifo_act <= 0;
      o_ppfifo_stb <= 0;
      o_ppfifo_data <= 0;
    end else begin
      case (state)
        IDLE: begin
          if (i_ppfifo_rdy[0]) begin
            state <= READY;
            r_count <= 0;
            o_ppfifo_act <= 1;
            o_ppfifo_stb <= 0;
            o_ppfifo_data <= 0;
          end
        end
        READY: begin
          if (i_ppfifo_rdy[0]) begin
            if (r_count < i_ppfifo_size[23:0]) begin
              if (!i_h_blank) begin
                o_ppfifo_stb <= 1;
                o_ppfifo_data <= i_rgb;
              end
              r_count <= r_count + 1;
            end else begin
              state <= RELEASE;
            end
          end
        end
        RELEASE: begin
          o_ppfifo_act <= 0;
          o_ppfifo_stb <= 0;
          o_ppfifo_data <= 0;
          state <= IDLE;
        end
      endcase
    end
  end

  assign o_ppfifo_clk = clk;

endmodule

