module routing_buffer(clock, resetn, 
  i_datain, i_datain_valid, o_datain_stall, 
  o_dataout, i_dataout_stall, o_dataout_valid);

 input clock, resetn;
 input [DATA_WIDTH-1:0] i_datain;
 input i_datain_valid;
 output reg o_datain_stall;
 output reg [DATA_WIDTH-1:0] o_dataout;
 input i_dataout_stall;
 output reg o_dataout_valid;
parameter DATA_WIDTH = 32;
 parameter INSERT_REGISTER = 1;

 reg [DATA_WIDTH-1:0] datain_reg;
 reg datain_valid_reg;
 reg dataout_valid_reg;

 always @ (posedge clock or negedge resetn)
 begin
  if (resetn == 1'b0)
  begin
   datain_reg <= {DATA_WIDTH{1'b0}};
   datain_valid_reg <= 1'b0;
   dataout_valid_reg <= 1'b0;
  end
  else
  begin
   datain_reg <= i_datain;
   datain_valid_reg <= i_datain_valid;
   dataout_valid_reg <= datain_valid_reg;
  end
 end

 assign o_datain_stall = i_datain_valid & ~datain_valid_reg;
 assign o_dataout = datain_reg;
 assign o_dataout_valid = dataout_valid_reg;

endmodule

