module data_deal(
	clk,
	rst_n,
	data_in,
	data_in_sign,

	data_out,
	data_out_sign,
	data_valid,
	data_ok
    );



	input 	clk;
	input 	rst_n;
	input 	[6:0]	data_in;
	input 	data_in_sign;

	output	[6:0]	data_out;
	output	data_out_sign;
	input 	data_valid;
	output	data_ok;
reg 	[6:0]	data_reg;
	reg 	[3:0]	data_regnum;
	reg 	data_out_sign;
	reg 	data_ok;
	reg 	[6:0]	data_out;

	always@(posedge clk or negedge rst_n)
	begin
		if(!rst_n)
		begin
			data_reg <= 0;
			data_regnum <= 0;
			data_out_sign <= 0;
			data_ok <= 0;
			data_out <= 0;
		end
		else
		begin
			if(data_in_sign)
				data_reg <= data_reg + data_in;
			data_regnum <= data_regnum + data_valid;
			if(data_regnum == 8)
				data_ok <= (data_reg == 28 || data_reg == 36);
			data_out_sign <= data_valid;
			if(data_out_sign)
				data_out <= data_out + 1;
		end
	end
endmodule

module clk_div(
