module toe_m_axis_rx_data_rsp_metadata_reg_slice
#(parameter
    N = 8   
) (

    input  wire         clk,
    input  wire         reset,

    input  wire [N-1:0] s_data,
    input  wire         s_valid,
    output wire         s_ready,

    output wire [N-1:0] m_data,
    output wire         m_valid,
    input  wire         m_ready
);
localparam [1:0]
    ZERO = 0,
    ONE  = 1,
    TWO  = 2;

reg [N-1:0] data_p1;
reg [N-1:0] data_p2;

reg load_p1;
reg load_p2;
reg load_p1_from_p2;

reg [1:0] state;
reg [1:0] next_state;

assign s_ready = (state == ZERO) ? 1'b1 : 1'b0;
assign m_data  = data_p1;
assign m_valid = (state == ONE) ? 1'b1 : 1'b0;

always @ (posedge clk) begin
    if (load_p1)
        data_p1 <= data_p2;
end

always @ (posedge clk) begin
    if (load_p2)
        data_p2 <= s_data;
end

always @ (posedge clk) begin
    if (reset == 1'b1) begin
        state <= ZERO;
    end else begin
        state <= next_state;
    end
end

always @ (*) begin
    case (state)
        ZERO:
            if (s_valid == 1'b1 && m_ready == 1'b1)
                next_state = ONE;
            else
                next_state = ZERO;
        ONE:
            if (s_valid == 1'b1 && m_ready == 1'b0)
                next_state = TWO;
            else
                next_state = ONE;
        TWO:
            if (s_valid == 1'b0 && m_ready == 1'b1)
                next_state = ZERO;
            else
                next_state = TWO;
        default:
            next_state = ZERO;
    endcase
end

always @ (*) begin
    load_p1 = 1'b0;
    load_p2 = 1'b0;
    load_p1_from_p2 = 1'b0;

    case (state)
        ZERO:
            if (s_valid == 1'b1 && m_ready == 1'b1) begin
                load_p1 = 1'b1;
                load_p2 = 1'b1;
            end
        ONE:
            if (s_valid == 1'b1 && m_ready == 1'b0) begin
                load_p1 = 1'b1;
                load_p2 = 1'b1;
                load_p1_from_p2 = 1'b1;
            end
        TWO:
            if (s_valid == 1'b0 && m_ready == 1'b1) begin
                load_p1 = 1'b1;
            end
        default:
    endcase
end

always @ (*) begin
    if (load_p1_from_p2)
        data_p1 = data_p2;
    else
        data_p1 = s_data;
end

endmodule

module Incer #(
    parameter DATA_WIDTH = 8
)
(clk,arstn,din,dout,mode);

input clk;
input arstn;
input mode;
input [DATA_WIDTH-1:0]din;
output [DATA_WIDTH-1:0]dout;
reg [DATA_WIDTH-1:0]counter;
reg [1:0]state;
parameter ADD_STATE = 2'b00;
parameter INC_STATE = 2'b01;

assign dout = counter;

always@(posedge clk or negedge arstn)
begin
    if(!arstn)
    begin
        counter <= 0;
        state <= ADD_STATE;
    end
    else
    begin
        case(state)
            ADD_STATE:
            begin
                if(mode)
                begin
                    counter <= din + 2;
                    state <= INC_STATE;
                end
                else
                begin
                    counter <= din + 1;
                end
            end
            INC_STATE:
            begin
                if(!mode)
                begin
                    counter <= 0;
                    state <= ADD_STATE;
                end
                else
                begin
                    counter <= counter + 1;
                end
            end
        endcase
    end
