module AXIS_WB_WB_Queue( 
  input         clock, 
  input         reset, 
  output        io_enq_ready, 
  input         io_enq_valid, 
  input  [31:0] io_enq_bits, 
  input         io_deq_ready, 
  output        io_deq_valid, 
  output [31:0] io_deq_bits 
);
wire  do_enq; 
  wire  do_deq; 
  wire  maybe_full; 
  wire  full; 
  wire  [9:0] value; 
  wire  [9:0] value_1; 
  reg [31:0] ram[0:511]; 
  assign io_enq_ready = ~maybe_full; 
  assign io_deq_valid = value != 0; 
  assign io_deq_bits = ram[value_1]; 
  assign do_enq = io_enq_valid & io_enq_ready; 
  assign do_deq = io_deq_ready & io_deq_valid; 
  assign maybe_full = value == 511; 
  assign full = maybe_full & io_enq_valid; 
  always @(posedge clock) begin
    if (reset) begin
      value <= 0;
    end else begin
      if (do_enq) begin
        value <= value + 1;
      end
      if (do_deq) begin
        value <= value - 1;
      end
    end
  end
  always @(posedge clock) begin
    if (reset) begin
      value_1 <= 0;
    end else begin
      if (do_deq) begin
        value_1 <= value_1 + 1;
      end
    end
  end
  always @(posedge clock) begin
    if (reset) begin
      ram[0] <= 0;
    end else begin
      if (do_enq) begin
        ram[value] <= io_enq_bits;
      end
    end
  end
endmodule

