module sparc_ifu_esl_lfsr
(
    input               clk,
    input               rst_n,


    input [15:0]        lfsr_seed,
    input               lfsr_ld,


    input               lfsr_step,


    output reg [15:0]   lfsr_state_f,


    output reg          lfsr_out_f
);
reg [15:0] lfsr_state_n;

always @(*) begin
    lfsr_state_n = lfsr_state_f;
    lfsr_out_f = lfsr_state_f[15];

    if (lfsr_ld) begin
        lfsr_state_n = lfsr_seed;
    end else if (lfsr_step) begin
        lfsr_state_n[15] = lfsr_state_f[15] ^ lfsr_state_f[14] ^ lfsr_state_f[13] ^ lfsr_state_f[12] ^ lfsr_state_f[11] ^ lfsr_state_f[10] ^ lfsr_state_f[9] ^ lfsr_state_f[8] ^ lfsr_state_f[7] ^ lfsr_state_f[6] ^ lfsr_state_f[5] ^ lfsr_state_f[4] ^ lfsr_state_f[3] ^ lfsr_state_f[2] ^ lfsr_state_f[1] ^ lfsr_state_f[0];
    end
end

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        lfsr_state_f <= 16'h0000;
    end else begin
        lfsr_state_f <= lfsr_state_n;
    end
end

endmodule

module mux4_1n (
    input EN_n,
    input A, B,
    input D0, D1, D2, D3,
    output Y
);
reg Y_reg;
    wire S = {A, B};

    always @(*) begin
        if (EN_n) begin
            Y_reg = 0;
        end else begin
            case (S)
                2'b00: Y_reg = D0;
                2'b01: Y_reg = D1;
                2'b10: Y_reg = D2;
                2'b11: Y_reg = D3;
            endcase
        end
    end

    assign Y = Y_reg;

endmodule

