module FFlr(
input wire clk,
input wire [31:0] f,
output reg [31:0] g
); 

reg [7:0] len_raw; reg [7:0] len; reg [31:0] x_mask; reg [31:0] f_masked; reg [31:0] f_incr; reg [31:0] f_out; reg [31:0] res;
  always @(posedge clk) begin
    len_raw <= f[30:23] - 8'b11111111;
    if((len_raw < 8'b00000000)) begin
      len <= 8'b00000000;
    end
    else if((len_raw > 8'b01111111)) begin
      len <= 8'b01111111;
    end
    else begin
      len <= len_raw;
    end
    x_mask <= {1'b0,{31{1'b1}}} >> len;
    f_masked <= f & x_mask;
    f_incr <= f_masked + 1;
    f_out <= f_masked;
    if((f[31] == 1'b1)) begin
      res <= {f[31],{31{1'b0}}};
    end
    else if((f[30:23] == 8'b00000000)) begin
      res <= f[31:23];
    end
    else if((f[30:23] == 8'b01111111)) begin
      res <= f[31:23];
    end
    else begin
      res <= f_out[31:23];
    end
    g <= res;
  end
endmodule

