            shift <= 1;
            latch <= 0;
        end else if (step_count == 9) begin
            data <= anodes[4];
            shift <= 0;
            latch <= 0;
        end else if (step_count == 10) begin
            data <= anodes[5];
            shift <= 1;
            latch <= 0;
        end else if (step_count == 11) begin
