module button_pulse 
#(
    parameter MAX_COUNT = 8,    
    parameter DEC_COUNT = 2,    
    parameter MIN_COUNT = 1     
)(
    input wire clk,
    input wire clk_en,
    input wire button,
    input wire reset,
    output wire pulse
);
reg [MAX_COUNT-1:0] comp = MAX_COUNT - 1;
    reg [MAX_COUNT-1:0] count = 0;
    assign pulse = (count == 0) & button;
    always @(posedge clk) begin
        if (reset) begin
            comp <= MAX_COUNT - 1;
            count <= 0;
        end else if (clk_en) begin
            if (button) begin
                count <= count + 1;
                if (count == 0) begin
                    comp <= comp - DEC_COUNT;
                    if (comp < MIN_COUNT) begin
                        comp <= MIN_COUNT;
                    end
                end
            end else begin
                count <= 0;
                comp <= MAX_COUNT - 1;
            end
        end
    end
endmodule

