module echo_server_application_m_axis_read_package_reg_slice
#(parameter
    N = 8   
) (

    input  wire         clk,
    input  wire         reset,

    input  wire [N-1:0] s_data,
    input  wire         s_valid,
    output wire         s_ready,

    output wire [N-1:0] m_data,
    output wire         m_valid,
    input  wire         m_ready
);
localparam [1:0]
    ZERO = 0,
    ONE  = 1,
    TWO  = 2;

reg [N-1:0] data_p1;
reg [N-1:0] data_p2;

reg load_p1;
reg load_p2;
reg load_p1_from_p2;

reg s_ready_t;

reg [1:0] state;
reg [1:0] next;

assign s_ready = s_ready_t;

assign m_data = data_p1;
assign m_valid = state[0];

always @(*) begin
    case (state)
        ZERO: next = s_valid ? ONE : ZERO;
        ONE:  next = m_ready ? TWO : ONE;
        TWO:  next = ONE;
        default: next = ZERO;
    endcase
end

always @(posedge clk) begin
    if (reset) begin
        state <= ZERO;
    end else begin
        state <= next;
    end
end

always @(*) begin
    load_p1 = 0;
    load_p2 = 0;
    load_p1_from_p2 = 0;

    case (state)
        ZERO: begin
            if (s_valid) begin
                load_p1 = 1;
            end
        end
        ONE: begin
            if (s_valid && ~m_ready) begin
                load_p1 = 1;
                load_p1_from_p2 = 1;
            end
            if (m_ready) begin
                load_p2 = 1;
            end
        end
        TWO: begin
            if (~s_valid) begin
                load_p2 = 1;
            end
        end
        default: begin
        end
    endcase
end

always @(posedge clk) begin
    if (load_p1) begin
        data_p1 <= s_data;
    end
    if (load_p1_from_p2) begin
        data_p1 <= data_p2;
    end
end

always @(posedge clk) begin
    if (load_p2) begin
        data_p2 <= data_p1;
    end
end

always @(posedge clk) begin
    if (reset) begin
        s_ready_t <= 0;
    end else begin
        case (state)
            ZERO: s_ready_t <= 1;
            ONE:  s_ready_t <= 0;
            TWO:  s_ready_t <= 1;
            default: s_ready_t <= 0;
        endcase
    end
end

endmodule

