module SynFifo #
(
    parameter DATA_WIDTH = 8,
    parameter FIFO_DEPTH = 256
)
(clk,arstn,data_in,wrreq,rdreq,data_out,usedw,empty,full);

input clk;
input arstn;
input [DATA_WIDTH-1:0]data_in;
input wrreq;
input rdreq;
output [DATA_WIDTH-1:0]data_out;
output reg [clog2_FIFO_DEPTH:0]usedw;
output empty;
output full;
parameter clog2_FIFO_DEPTH = $clog2(FIFO_DEPTH);

reg [clog2_FIFO_DEPTH:0]wrptr;
reg [clog2_FIFO_DEPTH:0]rdptr;
reg [clog2_FIFO_DEPTH:0]usedw_reg;
reg [DATA_WIDTH-1:0]fifo [0:FIFO_DEPTH-1];

wire wrreq_int = wrreq & ~full;
wire rdreq_int = rdreq & ~empty;

always @(posedge clk or negedge arstn)
begin
    if (~arstn)
    begin
        wrptr <= 0;
        rdptr <= 0;
        usedw_reg <= 0;
    end
    else
    begin
        if (wrreq_int)
        begin
            wrptr <= wrptr + 1;
            fifo[wrptr] <= data_in;
            usedw_reg <= usedw_reg + 1;
        end
        if (rdreq_int)
        begin
            rdptr <= rdptr + 1;
            usedw_reg <= usedw_reg - 1;
        end
    end
end

always @(posedge clk or negedge arstn)
begin
    if (~arstn)
    begin
        data_out <= 0;
    end
    else
    begin
        if (rdreq_int)
        begin
            data_out <= fifo[rdptr];
        end
    end
end

assign empty = (usedw_reg == 0);
assign full = (usedw_reg == FIFO_DEPTH);
assign usedw = usedw_reg;

endmodule

