module Data_CrossDomain(
    input clkA,
    input FlagIn_clkA, 
    input clkB,
    output FlagOut_clkB,
	input [7:0] dataA,
	output [7:0] dataB
);
reg FlagToggle_clkA;
reg [2:0] SyncA_clkB;
reg [7:0] clkA_data;
reg [7:0] clkB_data;

assign FlagOut_clkB = SyncA_clkB[2];

always @(posedge clkA) begin
	FlagToggle_clkA <= FlagIn_clkA;
end

always @(posedge clkB) begin
	SyncA_clkB <= {SyncA_clkB[1:0], FlagToggle_clkA};
end

always @(posedge clkA) begin
	clkA_data <= dataA;
end

always @(posedge clkB) begin
	if (SyncA_clkB[1] == 1'b1) begin
		clkB_data <= clkA_data;
	end
end

assign dataB = clkB_data;

endmodule

