module lfsr24(
input wire Clk,
input wire one,
input wire tick,
input wire [6:0] coreCount,
output reg data
); 

reg [23:0] lfsr_p;
reg [23:0] lfsr_n;
  always @(posedge Clk) begin
    if(one == 1'b1) begin
      lfsr_p <= 24'h020000;
    end
    else if(tick == 1'b1) begin
      lfsr_n <= lfsr_p;
      if(lfsr_p[23] == 1'b1) begin
        lfsr_n[23] <= lfsr_p[22] ^ lfsr_p[21] ^ lfsr_p[20] ^ lfsr_p[19] ^ lfsr_p[18] ^ lfsr_p[17] ^ lfsr_p[16] ^ lfsr_p[15] ^ lfsr_p[14] ^ lfsr_p[13] ^ lfsr_p[12] ^ lfsr_p[11] ^ lfsr_p[10] ^ lfsr_p[9] ^ lfsr_p[8] ^ lfsr_p[7] ^ lfsr_p[6] ^ lfsr_p[5] ^ lfsr_p[4] ^ lfsr_p[3] ^ lfsr_p[2] ^ lfsr_p[1] ^ lfsr_p[0];
      end
      else begin
        lfsr_n[23] <= lfsr_p[23];
      end
      lfsr_n[22] <= lfsr_p[23];
      lfsr_n[21] <= lfsr_p[22];
      lfsr_n[20] <= lfsr_p[21];
      lfsr_n[19] <= lfsr_p[20];
      lfsr_n[18] <= lfsr_p[19];
      lfsr_n[17] <= lfsr_p[18];
      lfsr_n[16] <= lfsr_p[17];
      lfsr_n[15] <= lfsr_p[16];
      lfsr_n[14] <= lfsr_p[15];
      lfsr_n[13] <= lfsr_p[14];
      lfsr_n[12] <= lfsr_p[13];
      lfsr_n[11] <= lfsr_p[12];
      lfsr_n[10] <= lfsr_p[11];
      lfsr_n[9] <= lfsr_p[10];
      lfsr_n[8] <= lfsr_p[9];
      lfsr_n[7] <= lfsr_p[8];
      lfsr_n[6] <= lfsr_p[7];
      lfsr_n[5] <= lfsr_p[6];
      lfsr_n[4] <= lfsr_p[5];
      lfsr_n[3] <= lfsr_p[4];
      lfsr_n[2] <= lfsr_p[3];
      lfsr_n[1] <= lfsr_p[2];
      lfsr_n[0] <= lfsr_p[1];
    end
    else begin
      lfsr_n <= lfsr_p;
    end
    lfsr_p <= lfsr_n;
  end
  always @(lfsr_p, coreCount) begin
    if(coreCount < 24) begin
      data <= lfsr_p[coreCount];
    end
    else begin
      data <= lfsr_p[23];
    end
  end
endmodule

