module serial2parallel(
    input clk,
    input rst_n,
    input din_serial,
    input din_valid,
    output reg [7:0] dout_parallel,
    output reg dout_valid
);
reg [7:0] shift_reg;
    reg [3:0] counter;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            dout_parallel <= 8'h00;
            dout_valid <= 1'b0;
            shift_reg <= 8'h00;
            counter <= 4'h0;
        end else begin
            if (din_valid) begin
                shift_reg <= {shift_reg[6:0], din_serial};
                counter <= counter + 1'b1;
                if (counter == 4'h7) begin
                    dout_parallel <= shift_reg;
                    dout_valid <= 1'b1;
                    counter <= 4'h0;
                end
            end else begin
                dout_valid <= 1'b0;
            end
        end
    end

endmodule

