            end
            if (A == B && A_equal == 0) begin
                $display("Error: A = %d, B = %d, A_equal = %d", A, B, A_equal);
                error = error + 1;
            end
            if (A < B && A_less == 0) begin
                $display("Error: A = %d, B = %d, A_less = %d", A, B, A_less);
                error = error + 1;
            end
        end
        if (error == 0) begin
            $display("Test passed!");
        end else begin
            $display("Test failed! %d errors", error);
        end
    end
endmodule

