module fsm_trafic_light(clk,reset, red,yellow, green);
input clk, reset;

output red,yellow,green;
reg [1:0] state, next_state;


always @(posedge clk or posedge reset) begin
	if (reset) state <= 0;
	else state <= next_state;
end

always @(*) begin
	case (state)
		0: next_state = 1;
		1: next_state = 2;
		2: next_state = 3;
		3: next_state = 0;
		default: next_state = 0;
	endcase
end

assign red = (state == 0);
assign yellow = (state == 1) || (state == 3);
assign green = (state == 2);

endmodule

