module submuladd_1_stage_signed_16_bit(
	input signed [15:0] a,
	input signed [15:0] b,
	input signed [15:0] c,
	input signed [15:0] d,
	output [15:0] out,
	input clk);
logic signed [31:0] stage0;

	always @(posedge clk) begin
	stage0 <= ((d - a) * b) + c;

	end

	assign out = stage0;
endmodule

module soundcodec(
	input	clk,
   input pulse,
   output o_pwm
);
reg [8:0] PWM_accumulator;
   reg state;
   always @(posedge clk) begin
      case (state)
         0: begin
            if (pulse) PWM_accumulator[8:0] <= PWM_accumulator[8:0] + 8'hFF;
            state <= 1;
         end
         1: begin
            state <= 0;
         end
      endcase
   end
   assign o_pwm = PWM_accumulator[8];
endmodule

module Adder(
	 input clock,
    input [31:0] input1,
    input [31:0] input2,
    output reg [31:0] result
    );
always @(negedge clock) begin
    result = input1 + input2;
  end
endmodule

