module key_filter(clk,rst_n,key_pin,key_status,key_event);
	input clk;
	input rst_n;
	input key_pin;
	output reg key_status;
	output reg key_event;
reg [2:0] state;
	reg [2:0] next_state;
	reg [2:0] edge;
	reg [2:0] edge_next;
	reg [2:0] edge_cnt;
	reg [2:0] edge_cnt_next;
	reg [2:0] edge_cnt_en;
	reg [2:0] edge_cnt_en_next;
	parameter idle = 3'b000;
	parameter press = 3'b001;
	parameter steady = 3'b010;
	parameter release = 3'b011;
	always @(posedge clk or negedge rst_n) begin
		if(!rst_n) begin
			state <= idle;
		end else begin
			state <= next_state;
		end
	end
	always @(*) begin
		case(state)
			idle: begin
				if(edge[0] == 1) begin
					next_state = press;
				end else begin
					next_state = idle;
				end
			end
			press: begin
				if(edge_cnt[0] == 1) begin
					next_state = steady;
				end else begin
					next_state = press;
				end
			end
			steady: begin
				if(edge[1] == 1) begin
					next_state = release;
				end else begin
					next_state = steady;
				end
			end
			release: begin
				if(edge_cnt[1] == 1) begin
					next_state = idle;
				end else begin
					next_state = release;
				end
			end
			default: begin
				next_state = idle;
			end
		endcase
	end
	always @(posedge clk or negedge rst_n) begin
		if(!rst_n) begin
			edge <= 3'b000;
		end else begin
			edge <= edge_next;
		end
	end
	always @(*) begin
		case(state)
			idle: begin
				edge_next = {edge[1:0],key_pin};
			end
			press: begin
				edge_next = {edge[1:0],key_pin};
			end
			steady: begin
				edge_next = {edge[1:0],key_pin};
			end
			release: begin
				edge_next = {edge[1:0],key_pin};
			end
			default: begin
				edge_next = 3'b000;
			end
		endcase
	end
	always @(posedge clk or negedge rst_n) begin
		if(!rst_n) begin
			edge_cnt <= 3'b000;
		end else begin
			edge_cnt <= edge_cnt_next;
		end
	end
	always @(*) begin
		case(state)
			idle: begin
				edge_cnt_next = 3'b000;
			end
			press: begin
				edge_cnt_next = edge_cnt_en;
			end
			steady: begin
				edge_cnt_next = edge_cnt_en;
			end
			release: begin
				edge_cnt_next = edge_cnt_en;
			end
			default: begin
				edge_cnt_next = 3'b000;
			end
		endcase
	end
	always @(posedge clk or negedge rst_n) begin
		if(!rst_n) begin
			edge_cnt_en <= 3'b000;
		end else begin
			edge_cnt_en <= edge_cnt_en_next;
		end
	end
	always @(*) begin
		case(state)
			idle: begin
				edge_cnt_en_next = 3'b000;
			end
			press: begin
				edge_cnt_en_next = 3'b000;
			end
			steady: begin
				edge_cnt_en_next = 3'b001;
			end
			release: begin
				edge_cnt_en_next = 3'b010;
			end
			default: begin
				edge_cnt_en_next = 3'b000;
			end
		endcase
	end
	always @(posedge clk or negedge rst_n) begin
		if(!rst_n) begin
			key_status <= 1'b0;
		end else begin
			case(state)
				idle: begin
					key_status <= 1'b0;
				end
				press: begin
					key_status <= 1'b0;
				end
				steady: begin
					key_status <= 1'b1;
				end
				release: begin
					key_status <= 1'b0;
				end
				default: begin
					key_status <= 1'b0;
				end
			endcase
		end
	end
	always @(posedge clk or negedge rst_n) begin
		if(!rst_n) begin
			key_event <= 1'b0;
		end else begin
			case(state)
				idle: begin
					key_event <= 1'b0;
				end
				press: begin
					key_event <= 1'b0;
				end
				steady: begin
					key_event <= 1'b0;
				end
				release: begin
					key_event <= 1'b1;
				end
				default: begin
					key_event <= 1'b0;
				end
			endcase
		end
	end
endmodule

module alu(input signed [31:0] x, input signed [31:0] y, input [3:0] alu_ctrl, output reg signed [31:0] result, output reg zero);
always @(*) begin
        case (alu_ctrl)
            4'b0000: result = x + y;
            4'b0001: result = x - y;
            4'b0010: result = x * y;
            4'b0011: result = x / y;
            4'b0100: result = x & y;
            4'b0101: result = x | y;
            4'b0110: result = x ^ y;
            4'b0111: result = x < y;
            default: result = 0;
        endcase
        zero = (result == 0);
    end
endmodule

