module tb_file_to_dvp
#(
	parameter FILE     = "in.bin",
	parameter BITS     = 8, 
	parameter H_FRONT  = 50,
	parameter H_PULSE  = 100,
	parameter H_BACK   = 50,
	parameter H_DISP   = 1280,
	parameter V_FRONT  = 10,
	parameter V_PULSE  = 20,
	parameter V_BACK   = 10,
	parameter V_DISP   = 960,
	parameter H_POL    = 0,
	parameter V_POL    = 1
)
(
	input             xclk,
	input             rst_n,
	output            pclk,
	output reg        href,
	output reg        hsync,
	output reg        vsync,
	output [BITS-1:0] data
);
reg [BITS-1:0] raw_data;
reg [31:0]     pix_cnt;
reg [31:0]     line_cnt;
reg [31:0]     data_cnt;
reg [31:0]     h_total;
reg [31:0]     v_total;

assign pclk = xclk;

initial begin
	$readmemb(FILE, raw_data);
end

always @(posedge xclk or negedge rst_n) begin
	if (!rst_n) begin
		pix_cnt <= 0;
		line_cnt <= 0;
		data_cnt <= 0;
		h_total <= H_FRONT + H_PULSE + H_BACK + H_DISP;
		v_total <= V_FRONT + V_PULSE + V_BACK + V_DISP;
	end else begin
		if (pix_cnt == h_total) begin
			pix_cnt <= 0;
			if (line_cnt == v_total) begin
				line_cnt <= 0;
			end else begin
				line_cnt <= line_cnt + 1;
			end
		end else begin
			pix_cnt <= pix_cnt + 1;
		end
		if (pix_cnt < H_FRONT) begin
			hsync <= H_POL;
		end else if (pix_cnt < H_FRONT + H_PULSE) begin
			hsync <= ~H_POL;
		end else begin
			hsync <= H_POL;
		end
		if (line_cnt < V_FRONT) begin
			vsync <= V_POL;
		end else if (line_cnt < V_FRONT + V_PULSE) begin
			vsync <= ~V_POL;
		end else begin
			vsync <= V_POL;
		end
		if (pix_cnt >= H_FRONT && pix_cnt < H_FRONT + H_PULSE && line_cnt >= V_FRONT && line_cnt < V_FRONT + V_PULSE) begin
			href <= 1;
			data <= raw_data[data_cnt];
			data_cnt <= data_cnt + 1;
		end else begin
			href <= 0;
			data <= 0;
		end
	end
end

endmodule

