module maxFinder #(parameter numInput=10,parameter inputWidth=16)(
input           i_clk,
input [(numInput*inputWidth)-1:0]   i_data,
input           i_valid,
output reg [31:0]o_data,
output  reg     o_data_valid
);
reg [inputWidth-1:0] maxValue;
reg [(numInput*inputWidth)-1:0] inDataBuffer;
reg [31:0] counter;
always @(posedge i_clk) begin
    if (i_valid) begin
        counter <= 0;
        o_data_valid <= 0;
    end
    else if (counter < numInput) begin
        inDataBuffer[(counter+1)*inputWidth-1:counter*inputWidth] <= i_data[(counter+1)*inputWidth-1:counter*inputWidth];
        if (counter == 0) begin
            maxValue <= inDataBuffer[(counter+1)*inputWidth-1:counter*inputWidth];
            o_data <= counter;
        end
        else begin
            if (inDataBuffer[(counter+1)*inputWidth-1:counter*inputWidth] > maxValue) begin
                maxValue <= inDataBuffer[(counter+1)*inputWidth-1:counter*inputWidth];
                o_data <= counter;
            end
        end
        counter <= counter + 1;
    end
    else begin
        o_data_valid <= 1;
    end
end
endmodule

