module KEY_MUX
(
	input PS2_CLK,
	input PS2_DAT,
	output [9:0]LEDR,
	output [6:0]HEX0,
	output [6:0]HEX1
);
wire [7:0]scan_code;
	assign LEDR = {NS, S};
	assign HEX0 = in3;
	assign HEX1 = in1;

	reg [3:0]S, NS;
	reg [7:0]in1, in2, in3, out;

	always @ (posedge scan_code)
	begin
		case (S)
			4'b0000: begin
				in1 <= scan_code;
				NS <= 4'b0001;
			end
			4'b0001: begin
				in2 <= scan_code;
				NS <= 4'b0010;
			end
			4'b0010: begin
				in3 <= scan_code;
				NS <= 4'b0011;
			end
			4'b0011: begin
				out <= scan_code;
				NS <= 4'b0000;
			end
			default: NS <= 4'b0000;
		endcase
	end

	keyboard key(.clk(PS2_CLK), .data(PS2_DAT), .scan_code(scan_code));
	display7seg disp(.data(out), .seg(HEX0));

endmodule

