module hardcopyiv_ram_register (
                             d,
                             clk,
                             aclr,
                             devclrn,
                             devpor,
                             stall,
                             ena,
                             q,
                             aclrout
                            );  

input [width - 1:0] d;    
input clk;                
input aclr;               
input devclrn,devpor;     
input stall; 
input ena;                
output [width - 1:0] q;   
output aclrout;
parameter width = 1;
parameter lpm_type = "hardcopyiv_ram_register";

reg [width - 1:0] data_out_tmp;
reg [width - 1:0] data_out_tmp_d;
reg aclr_tmp;
reg aclr_tmp_d;

wire [width - 1:0] d_in;
wire clk_in;
wire aclr_in;
wire devclrn_in;
wire devpor_in;
wire stall_in;
wire ena_in;

buf d_in_buf(d_in,d);
buf clk_in_buf(clk_in,clk);
buf aclr_in_buf(aclr_in,aclr);
buf devclrn_in_buf(devclrn_in,devclrn);
buf devpor_in_buf(devpor_in,devpor);
buf stall_in_buf(stall_in,stall);
buf ena_in_buf(ena_in,ena);

specify
    (clk => (q, aclrout)) = (0, 0);
    (d => (q, aclrout)) = (0, 0);
    (aclr => (q, aclrout)) = (0, 0);
endspecify

initial
begin
    aclr_tmp = 1'b0;
    data_out_tmp = {width{1'b0}};
end

always @ (posedge clk_in or posedge devclrn_in or posedge devpor_in)
begin
    if (devclrn_in == 1'b0 || devpor_in == 1'b0)
    begin
        aclr_tmp <= 1'b0;
        data_out_tmp <= {width{1'b0}};
    end
    else if (aclr_in == 1'b1)
    begin
        aclr_tmp <= 1'b1;
        data_out_tmp <= {width{1'b0}};
    end
    else if (stall_in == 1'b0 && ena_in == 1'b1)
    begin
        aclr_tmp <= 1'b0;
        data_out_tmp <= d_in;
    end
end

always @ (posedge clk_in or posedge devclrn_in or posedge devpor_in)
begin
    if (devclrn_in == 1'b0 || devpor_in == 1'b0)
    begin
        aclr_tmp_d <= 1'b0;
    end
    else
    begin
        aclr_tmp_d <= aclr_tmp;
    end
end

always @ (posedge clk_in or posedge devclrn_in or posedge devpor_in)
begin
    if (devclrn_in == 1'b0 || devpor_in == 1'b0)
    begin
        data_out_tmp_d <= {width{1'b0}};
    end
    else
    begin
        data_out_tmp_d <= data_out_tmp;
    end
end

buf aclrout_buf(aclrout,aclr_tmp_d);
buf q_buf(q,data_out_tmp_d);

endmodule

