module datapath(clk, startGameEn, user_x, user_y, enemy_x, enemy_y, enem_grid, x, y, colour);
input clk; 
	input startGameEn; 
	input [7:0]user_x; 
	input [6:0]user_y; 
	input [7:0]enemy_x; 
	input [6:0]enemy_y; 
	input [160*120-1:0] enem_grid; 
	output reg [7:0] x; 
	output reg [6:0] y; 
	output reg[2:0] colour;
reg clear;
	always @(posedge clk) begin
		if(startGameEn) begin
			x <= 0;
			y <= 0;
			clear <= 1;
		end
		else begin
			if(x == 160) begin
				x <= 0;
				y <= y + 1;
			end
			else begin
				x <= x + 1;
			end
			if(clear) begin
				colour <= 3'b000;
				clear <= 0;
			end
			else begin
				if(x == user_x && y == user_y) begin
					colour <= 3'b100;
				end
				else if(x == enemy_x && y == enemy_y) begin
					colour <= 3'b010;
				end
				else if(enem_grid[160*y + x] == 1) begin
					colour <= 3'b001;
				end
				else begin
					colour <= 3'b000;
				end
			end
		end
	end
endmodule

