module soc_system_mm_interconnect_4_cmd_mux_002
(



    input                       sink0_valid,
    input [129-1   : 0]  sink0_data,
    input [11-1: 0]  sink0_channel,
    input                       sink0_startofpacket,
    input                       sink0_endofpacket,
    output                      sink0_ready,

    input                       sink1_valid,
    input [129-1   : 0]  sink1_data,
    input [11-1: 0]  sink1_channel,
    input                       sink1_startofpacket,
    input                       sink1_endofpacket,
    output                      sink1_ready,





    output                      src_valid,
    output [129-1    : 0] src_data,
    output [11-1 : 0] src_channel,
    output                      src_startofpacket,
    output                      src_endofpacket,
    input                       src_ready,




    input clk,
    input reset
);
localparam PAYLOAD_W        = 129 + 11 + 2;
    localparam NUM_INPUTS       = 2;
    localparam SHARE_COUNTER_W  = 1;
    localparam PIPELINE_ARB     = 1;
    localparam ST_DATA_W        = 129;
    localparam ST_CHANNEL_W     = 11;
    localparam PKT_TRANS_LOCK   = 64;

    localparam SHARE_COUNTER_MASK = (NUM_INPUTS > 1) ? SHARE_COUNTER_W - 1 : 0;
    reg [SHARE_COUNTER_W - 1 : 0] share_counter = 0;
    reg [NUM_INPUTS - 1 : 0] sink_valid;
    wire [NUM_INPUTS - 1 : 0] sink_ready;
    reg [NUM_INPUTS - 1 : 0] next_sink_ready;
    reg [PAYLOAD_W - 1 : 0]  current_payload;
    reg [ST_CHANNEL_W - 1 : 0] current_channel;
    reg                      current_start_of_packet;
    reg                      current_end_of_packet;
    reg [SHARE_COUNTER_W - 1 : 0]  current_share_counter;
    reg                      next_start_of_packet;
    reg                      next_end_of_packet;
    reg [SHARE_COUNTER_W - 1 : 0]  next_share_counter;
    reg [PAYLOAD_W - 1 : 0]  next_payload;
    reg [ST_CHANNEL_W - 1 : 0] next_channel;
    reg                      ready_vector;
    reg                      next_ready_vector;

    assign src_valid          = sink_valid[0] | sink_valid[1];
    assign src_data           = current_payload[ST_DATA_W - 1 : 0];
    assign src_channel        = current_channel;
    assign src_startofpacket  = current_start_of_packet;
    assign src_endofpacket    = current_end_of_packet;
    assign sink0_ready        = sink_ready[0];
    assign sink1_ready        = sink_ready[1];

    always @* begin
        sink_valid[0] = 0;
        sink_valid[1] = 0;
        sink_ready[0] = 0;
        sink_ready[1] = 0;
        next_ready_vector = 0;

        case (ready_vector)
            2'b00 : begin
                sink_valid[0] = sink0_valid;
                sink_ready[0] = src_ready;
                next_ready_vector = 1'b1;
            end
            2'b01 : begin
                sink_valid[1] = sink1_valid;
                sink_ready[1] = src_ready;
                next_ready_vector = 1'b10;
            end
            2'b10 : begin
                sink_valid[0] = sink0_valid;
                sink_ready[0] = src_ready;
                next_ready_vector = 1'b1;
            end
            2'b11 : begin
                sink_valid[0] = sink0_valid;
                sink_ready[0] = src_ready;
                sink_valid[1] = sink1_valid;
                sink_ready[1] = src_ready;
                next_ready_vector = 1'b11;
            end
        endcase
    end

    always @* begin
        next_payload = current_payload;
        next_channel = current_channel;
        next_start_of_packet = current_start_of_packet;
        next_end_of_packet = current_end_of_packet;
        next_share_counter = current_share_counter;

        case (ready_vector)
            2'b00 : begin
                if (sink0_valid) begin
                    next_payload = {sink0_data, sink0_channel, {PIPELINE_ARB{1'b0}}};
                    next_channel = sink0_channel;
                    next_start_of_packet = sink0_startofpacket;
                    next_end_of_packet = sink0_endofpacket;
                    next_share_counter = share_counter[SHARE_COUNTER_MASK:0];
                end
            end
            2'b01 : begin
                if (sink1_valid) begin
                    next_payload = {sink1_data, sink1_channel, {PIPELINE_ARB{1'b0}}};
                    next_channel = sink1_channel;
                    next_start_of_packet = sink1_startofpacket;
                    next_end_of_packet = sink1_endofpacket;
                    next_share_counter = share_counter[SHARE_COUNTER_MASK:0];
                end
            end
            2'b10 : begin
                if (sink0_valid) begin
                    next_payload = {sink0_data, sink0_channel, {PIPELINE_ARB{1'b0}}};
                    next_channel = sink0_channel;
                    next_start_of_packet = sink0_startofpacket;
                    next_end_of_packet = sink0_endofpacket;
                    next_share_counter = share_counter[SHARE_COUNTER_MASK:0];
                end
            end
            2'b11 : begin
                if (sink0_valid) begin
                    next_payload = {sink0_data, sink0_channel, {PIPELINE_ARB{1'b0}}};
                    next_channel = sink0_channel;
                    next_start_of_packet = sink0_startofpacket;
                    next_end_of_packet = sink0_endofpacket;
                    next_share_counter = share_counter[SHARE_COUNTER_MASK:0];
                end
                else if (sink1_valid) begin
                    next_payload = {sink1_data, sink1_channel, {PIPELINE_ARB{1'b0}}};
                    next_channel = sink1_channel;
                    next_start_of_packet = sink1_startofpacket;
                    next_end_of_packet = sink1_endofpacket;
                    next_share_counter = share_counter[SHARE_COUNTER_MASK:0];
                end
            end
        endcase
    end

    always @(posedge clk) begin
        if (reset) begin
            share_counter <= 0;
        end
        else if (PIPELINE_ARB == 0) begin
            share_counter <= share_counter + 1;
        end
        else begin
            share_counter <= share_counter + next_ready_vector;
        end
    end

    always @(posedge clk) begin
        if (reset) begin
            current_payload          <= 0;
            current_channel          <= 0;
            current_start_of_packet  <= 0;
            current_end_of_packet    <= 0;
            current_share_counter    <= 0;
            ready_vector             <= 0;
        end
        else begin
            current_payload          <= next_payload;
            current_channel          <= next_channel;
            current_start_of_packet  <= next_start_of_packet;
            current_end_of_packet    <= next_end_of_packet;
            current_share_counter    <= next_share_counter;
            ready_vector             <= next_ready_vector;
        end
    end


endmodule

module file_writer(input_a,input_a_stb,clk,rst,input_a_ack);

  input     clk;
  input     rst;

  input     [63:0] input_a;
  input     input_a_stb;
  output    input_a_ack;
reg       input_a_ack;

  reg       [1:0] state;
  reg       [63:0] value;
  reg       s_input_a_ack;

  reg       [31:0] file_handle;

  initial begin
    state = 0;
    input_a_ack = 0;
    s_input_a_ack = 0;
    file_handle = 0;
  end

  always @(posedge clk or posedge rst) begin
    if (rst) begin
      state <= 0;
      input_a_ack <= 0;
      s_input_a_ack <= 0;
      file_handle <= 0;
    end else begin
      case (state)
        0: begin
          if (input_a_stb) begin
            value <= input_a;
            state <= 1;
            input_a_ack <= 1;
            s_input_a_ack <= 1;
          end
        end
        1: begin
          if (s_input_a_ack) begin
            file_handle = $fopena("resp_z");
            $fdisplay(file_handle,"%h",value[63:32]);
            $fdisplay(file_handle,"%h",value[31:0]);
            $fclose(file_handle);
            state <= 0;
            input_a_ack <= 0;
            s_input_a_ack <= 0;
          end
        end
      endcase
    end
  end

endmodule

