module BaudTickGen(
	input clk, enable,
	output tick  
);
parameter ClkFrequency = 100000000;  
	parameter Baud = 9600;  
	parameter Oversampling = 16;  

	function integer log2(input integer v);
		begin
			log2 = 0;
			while (v > 1) begin
				v = v >> 1;
				log2 = log2 + 1;
			end
		end
	endfunction
	
	localparam AccBits = log2(ClkFrequency / Baud / Oversampling);
	reg [AccBits-1:0] Acc = 0;
	wire [AccBits-1:0] Inc = ClkFrequency / Baud / Oversampling;
	
	always @(posedge clk) begin
		if (enable)
			Acc <= Acc + Inc;
		else
			Acc <= 0;
	end
	
	assign tick = Acc[AccBits-1];
	
endmodule

