	stage1 <= stage0;
	end

	assign out = stage1;
endmodule

module vga_sync_pulse
(
    input   i_clk,
    output  o_hsync,
    output  o_vsync,
    output reg [9:0] o_col_count = 0,
    output reg [9:0] o_row_count = 0
);
parameter COLS = 640;
    parameter ROWS = 480;
    parameter HBLANK = 160;
    parameter VBLANK = 10;

    reg hsync = 0;
    reg vsync = 0;

    always @(posedge i_clk) begin
        o_col_count <= o_col_count + 1;
        o_row_count <= o_row_count + 1;

        if (o_col_count == COLS) begin
            o_col_count <= 0;
        end

        if (o_row_count == ROWS) begin
            o_row_count <= 0;
        end

        if (o_col_count < HBLANK) begin
            hsync <= 1;
        end else begin
            hsync <= 0;
        end

        if (o_row_count < VBLANK) begin
            vsync <= 1;
        end else begin
            vsync <= 0;
        end
    end

    assign o_hsync = hsync;
    assign o_vsync = vsync;

endmodule

