module bridge_1x2(                                 
    input                           clk,          
    input                           resetn,       
    input                           cpu_data_en,      
    input  [3                   :0] cpu_data_wen,     
    input  [31                  :0] cpu_data_addr,    
    input  [31                  :0] cpu_data_wdata,   
    output [31                  :0] cpu_data_rdata,   
    output                          data_sram_en,     
    output [3                   :0] data_sram_wen,    
    output [31                  :0] data_sram_addr,   
    output [31                  :0] data_sram_wdata,  
    input  [31                  :0] data_sram_rdata,  
    output                          conf_en,          
    output [3                   :0] conf_wen,         
    output [31                  :0] conf_addr,        
    output [31                  :0] conf_wdata,       
    input  [31                  :0] conf_rdata        
);
localparam CONF_ADDR_BASE = 32'h00000000;
    localparam CONF_ADDR_MASK = 32'h0000000F;

    reg sel_sram;
    reg sel_conf;

    assign data_sram_en = sel_sram & cpu_data_en;
    assign data_sram_wen = cpu_data_wen;
    assign data_sram_addr = cpu_data_addr;
    assign data_sram_wdata = cpu_data_wdata;
    assign cpu_data_rdata = sel_sram ? data_sram_rdata : 32'h00000000;

    assign conf_en = sel_conf & cpu_data_en;
    assign conf_wen = cpu_data_wen;
    assign conf_addr = cpu_data_addr;
    assign conf_wdata = cpu_data_wdata;
    assign cpu_data_rdata = sel_conf ? conf_rdata : cpu_data_rdata;

    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            sel_sram <= 1'b0;
            sel_conf <= 1'b0;
        end else begin
            sel_sram <= (cpu_data_addr[31:28] == 4'h0);
            sel_conf <= (cpu_data_addr[31:28] == 4'h0) && (cpu_data_addr[3:0] == CONF_ADDR_MASK);
        end
    end

endmodule

