  input   [BUS_WIDTH/8-1:0]         i_bus_strobe,
  output                            o_bus_ready,
  output  [1:0]                     o_bus_status,
  output  [BUS_WIDTH-1:0]           o_bus_read_data,
  output                            o_psel,
  output                            o_penable,
  output  [ADDRESS_WIDTH-1:0]       o_paddr,
  output  [2:0]                     o_pprot,
  output                            o_pwrite,
  output  [BUS_WIDTH/8-1:0]         o_pstrb,
  output  [BUS_WIDTH-1:0]           o_pwdata,
  input                             i_pready,
  input   [BUS_WIDTH-1:0]           i_prdata,
  input                             i_pslverr
);
reg busy;

  wire bus_ready;
  wire bus_status;
  wire bus_read_data;
  wire psel;
  wire penable;
  wire paddr;
  wire pprot;
  wire pwrite;
  wire pstrb;
  wire pwdata;

  assign o_bus_ready = bus_ready;
  assign o_bus_status = bus_status;
  assign o_bus_read_data = bus_read_data;
  assign o_psel = psel;
  assign o_penable = penable;
  assign o_paddr = paddr;
  assign o_pprot = pprot;
  assign o_pwrite = pwrite;
  assign o_pstrb = pstrb;
  assign o_pwdata = pwdata;

  always @(posedge i_clk or negedge i_rst_n) begin
    if (i_rst_n == 1'b0) begin
      busy <= 1'b0;
    end else begin
      case (busy)
        1'b0: begin
          if (i_bus_valid) begin
            busy <= 1'b1;
          end
        end
        1'b1: begin
          if (i_pready) begin
            busy <= 1'b0;
          end
        end
      endcase
    end
  end

  assign bus_ready = ~busy;
  assign bus_status = i_pslverr ? 2'b11 : 2'b00;
  assign bus_read_data = i_prdata;
  assign psel = i_bus_valid && bus_ready;
  assign penable = i_bus_valid && bus_ready;
  assign paddr = i_bus_address;
  assign pprot = 3'b000;
  assign pwrite = i_bus_access[0];
  assign pstrb = i_bus_strobe;
  assign pwdata = i_bus_write_data;

endmodule

