module db (
        input clk, n_reset, button_in,
        output reg out
    );
parameter maxbit = 10;
    reg [maxbit-1:0] q_reg, q_next;
    reg f1, f2;
    wire q_add, q_reset;
    assign q_add = ~q_reg[maxbit-1];
    assign q_reset = ~f1 & f2;
    always @(posedge clk or negedge n_reset) begin
        if (!n_reset) begin
            q_reg <= {maxbit{1'b0}};
        end else begin
            case ({q_add, q_reset})
                2'b01: q_reg <= {maxbit{1'b0}};
                2'b10: q_reg <= q_reg + 1;
                default: q_reg <= q_reg;
            endcase
        end
    end
    always @(posedge clk or negedge n_reset) begin
        if (!n_reset) begin
            f1 <= 1'b0;
            f2 <= 1'b0;
            out <= 1'b0;
        end else begin
            f1 <= button_in;
            f2 <= f1;
            if (q_reg == (2**maxbit - 1)) begin
                out <= f1;
            end
        end
    end
endmodule

