module FIFO(
    input clock,
    input sclr,
    input rdreq, wrreq,
    output reg full, empty,
    input [7 : 0] data,
    output [7 : 0] q
);
reg [7 : 0] mem [0 : 15];
    reg [3 : 0] wp, rp;
    reg w_flag, r_flag;
    always @(posedge clock or posedge sclr) begin
        if (sclr) begin
            wp <= 4'b0000;
            rp <= 4'b0000;
            w_flag <= 1'b0;
            r_flag <= 1'b0;
        end else begin
            if (wrreq) begin
                mem[wp] <= data;
                if (wp == 4'b1111) begin
                    wp <= 4'b0000;
                    w_flag <= 1'b1;
                end else begin
                    wp <= wp + 1;
                end
            end
            if (rdreq) begin
                q <= mem[rp];
                if (rp == 4'b1111) begin
                    rp <= 4'b0000;
                    r_flag <= 1'b1;
                end else begin
                    rp <= rp + 1;
                end
            end
        end
    end
    always @(*) begin
        if (w_flag && r_flag) begin
            full = 1'b0;
            empty = 1'b0;
        end else if (w_flag) begin
            full = 1'b0;
            empty = 1'b1;
        end else if (r_flag) begin
            full = 1'b1;
            empty = 1'b0;
        end else begin
            if (wp == rp) begin
                full = 1'b0;
                empty = 1'b1;
            end else if (wp == rp + 1) begin
                full = 1'b1;
                empty = 1'b0;
            end else begin
                full = 1'b0;
                empty = 1'b0;
            end
        end
    end
endmodule

