module I_SQRT_2(
input wire [31:0] n,
input wire CLK,
input wire RST_n,
input wire EN,
input wire SEL,
output wire VAL,
output wire Z,
output wire [31:0] out_sqrt
); 

reg [31:0] x_0 = 1.0;  
reg [31:0] x_i;
reg [31:0] x_next;
reg [31:0] sqrt;
reg [31:0] x_i_mux;
reg val_comb = 1'b0;
reg z_comb = 1'b0;
reg val_ff = 1'b0;
reg z_ff = 1'b0;
reg out_sqrt_reg = 1'b0;
  always @(posedge CLK) begin
    if((n == 0)) begin
      sqrt <= 0;
      val_comb <= 1'b0;
      z_comb <= 1'b1;
    end
    else if((x_next >= x_i)) begin
      sqrt <= x_i;
      val_comb <= 1'b1;
      z_comb <= 1'b0;
    end
    else begin
      val_comb <= 1'b0;
      z_comb <= 1'b0;
    end
  end
  always @(posedge CLK) begin
    if((RST_n == 1'b0)) begin
      val_ff <= 1'b0;
      z_ff <= 1'b0;
    end
    else begin
      val_ff <= val_comb;
      z_ff <= z_comb;
    end
  end
  always @(posedge CLK) begin
    if((EN == 1'b1)) begin
      out_sqrt_reg <= sqrt;
    end
  end
  assign out_sqrt = out_sqrt_reg;
  assign VAL = val_ff;
  assign Z = z_ff;
  assign x_i_mux = (SEL == 1'b0) ? x_0 : x_next;
  always @(posedge CLK) begin
    if((RST_n == 1'b0)) begin
      x_i <= 0;
    end
    else begin
      x_i <= x_i_mux;
    end
  end
  always @(posedge CLK) begin
    if((RST_n == 1'b0)) begin
      x_next <= 0;
    end
    else begin
      x_next <= (x_i + (n / x_i)) >> 1;
    end
  end
endmodule

