   initial q_out = 1'b0;

   always @ (D or ENA or PRE or CLR)
   begin
      if (PRE == 1'b1)
         q_out <= 1'b1;
      else if (CLR == 1'b1)
         q_out <= 1'b0;
      else if (ENA == 1'b1)
         q_out <= D;
   end
endmodule

