module NBitCounterChain #(
   parameter counterSize   = 16,
   parameter numOfCounters = 3054
) (
   input  wire                   clk,
   input  wire                   reset,
   output wire [counterSize-1:0] outCount
);
reg [counterSize-1:0] counts [numOfCounters-1:0];
   reg terminalCounts [numOfCounters-1:0];
   wire [counterSize-1:0] outCounts [numOfCounters-1:0];
   wire [counterSize-1:0] enables [numOfCounters-1:0];
   genvar i;
   generate
      for (i = 0; i < numOfCounters; i = i + 1) begin : counterChain
         Counter #(
            .counterSize(counterSize)
         ) counter (
            .clk(clk),
            .reset(reset),
            .count(counts[i]),
            .terminalCount(terminalCounts[i]),
            .outCount(outCounts[i]),
            .enable(enables[i])
         );
         if (i == 0) begin
            enables[i] <= 1'b1;
         end else begin
            enables[i] <= terminalCounts[i-1];
         end
      end
   endgenerate
   assign outCount = outCounts[numOfCounters-1];
endmodule

