module vga_sync(
input wire clk,
input wire rst,
output reg active,
output reg hsync,
output reg vsync,
output wire [9:0] xaddr,
output wire [9:0] yaddr
); 

parameter [31:0] hsize=640;
parameter [31:0] hfront=16;
parameter [31:0] hback=48;
parameter [31:0] hretrace=96;
parameter [31:0] vsize=480;
parameter [31:0] vfront=10;
parameter [31:0] vback=33;
parameter [31:0] vretrace=2;
reg [9:0] h_count_reg = 0;
reg [9:0] v_count_reg = 0;
  always @(posedge clk) begin
    if((rst == 1'b1)) begin
      h_count_reg <= 0;
      v_count_reg <= 0;
    end
    else begin
      if((h_count_reg == (hsize + hfront + hback + hretrace - 1))) begin
        h_count_reg <= 0;
        if((v_count_reg == (vsize + vfront + vback + vretrace - 1))) begin
          v_count_reg <= 0;
        end
        else begin
          v_count_reg <= v_count_reg + 1;
        end
      end
      else begin
        h_count_reg <= h_count_reg + 1;
      end
    end
  end
  assign xaddr = h_count_reg;
  assign yaddr = v_count_reg;
  always @(h_count_reg, v_count_reg) begin
    if((h_count_reg >= hfront) && (h_count_reg < (hfront + hsize))) begin
      hsync <= 1'b0;
    end
    else begin
      hsync <= 1'b1;
    end
    if((v_count_reg >= vfront) && (v_count_reg < (vfront + vsize))) begin
      vsync <= 1'b0;
    end
    else begin
      vsync <= 1'b1;
    end
    if((h_count_reg >= hfront) && (h_count_reg < (hfront + hsize)) && (v_count_reg >= vfront) && (v_count_reg < (vfront + vsize))) begin
      active <= 1'b1;
    end
    else begin
      active <= 1'b0;
    end
  end
endmodule

