    output reg [255:0] q
);
reg [255:0] next;
    reg [255:0] n;
    integer i, j, k;
    always @(posedge clk) begin
        if (load) begin
            q <= data;
        end else begin
            for (i = 0; i < 256; i = i + 1) begin
                n[i] <= 0;
            end
            for (i = 0; i < 16; i = i + 1) begin
                for (j = 0; j < 16; j = j + 1) begin
                    for (k = 0; k < 8; k = k + 1) begin
                        n[i*16+j] <= n[i*16+j] + q[(i+((k>>3)&1))*16+j+((k&7)-4)];
