            end
            for (i = 0; i < 256; i = i + 1) begin
                if (n[i] < 2) begin
                    next[i] <= 0;
                end else if (n[i] == 2) begin
                    next[i] <= q[i];
                end else if (n[i] == 3) begin
                    next[i] <= 1;
                end else begin
                    next[i] <= 0;
                end
            end
            q <= next;
        end
    end
