module TopModule(
    input clk,
    input resetn,
    input [2:0] r,
    output reg [2:0] g
);
reg [1:0] state, next_state;

always @(*) begin
    case (state)
        2'b00: begin
            if (r[0] == 1'b0 && r[1] == 1'b0 && r[2] == 1'b0)
                next_state = 2'b00;
            else if (r[0] == 1'b1)
                next_state = 2'b01;
            else if (r[0] == 1'b0 && r[1] == 1'b1)
                next_state = 2'b10;
            else if (r[0] == 1'b0 && r[1] == 1'b0 && r[2] == 1'b1)
                next_state = 2'b11;
        end
        2'b01: begin
            if (r[0] == 1'b1)
                next_state = 2'b01;
            else
                next_state = 2'b00;
        end
        2'b10: begin
            if (r[1] == 1'b1)
                next_state = 2'b10;
            else
                next_state = 2'b00;
        end
        2'b11: begin
            next_state = 2'b11;
        end
    endcase
end

always @(posedge clk or negedge resetn) begin
    if (!resetn) begin
        state <= 2'b00;
    end else begin
        state <= next_state;
    end
end

always @(*) begin
    case (state)
        2'b00: begin
            g = 3'b000;
        end
        2'b01: begin
            g = 3'b001;
        end
        2'b10: begin
            g = 3'b010;
        end
        2'b11: begin
            g = 3'b011;
        end
    endcase
end

endmodule

