module TopModule(
    input wire clk,
    input wire areset,
    input wire bump_left,
    input wire bump_right,
    input wire ground,
    input wire dig,
    output reg walk_left,
    output reg walk_right,
    output reg aaah,
    output reg digging
);
reg falling;
    reg falling_last;
    reg digging_last;
    reg falling_next;
    reg digging_next;
    reg walk_left_next;
    reg walk_right_next;
    reg aaah_next;
    reg digging_next;
    always @(posedge clk) begin
        falling <= falling_next;
        walking_left <= walk_left_next;
        walking_right <= walk_right_next;
        aaah <= aaah_next;
        digging <= digging_next;
    end
    always @(*) begin
        falling_next = falling_last;
        walk_left_next = walk_left;
        walk_right_next = walk_right;
        aaah_next = aaah;
        digging_next = digging_last;
        if (areset) begin
            walking_left = 1;
            walking_right = 0;
            aaah = 0;
            digging = 0;
            falling_next = 0;
            walking_left_next = 1;
            walking_right_next = 0;
            aaah_next = 0;
            digging_next = 0;
        end else begin
            if (ground == 0) begin
                aaah_next = 1;
                walking_left_next = 0;
                walking_right_next = 0;
                falling_next = 1;
            end else begin
                aaah_next = 0;
                if (falling_last) begin
                    walking_left_next = 0;
                    walking_right_next = 0;
                    falling_next = 0;
                end else begin
                    if (digging_last) begin
                        walking_left_next = 0;
                        walking_right_next = 0;
                        digging_next = 0;
                        falling_next = 0;
                    end else begin
                        if (bump_left) begin
                            walking_left_next = 0;
                            walking_right_next = 1;
                        end else begin
                            if (bump_right) begin
                                walking_left_next = 1;
                                walking_right_next = 0;
                            end else begin
                                walking_left_next = walk_left;
                                walking_right_next = walk_right;
                            end
                        end
                    end
                end
            end
            if (dig) begin
                digging_next = 1;
            end else begin
                digging_next = 0;
            end
        end
    end
endmodule

module TopModule(
    input wire clk,
    input wire areset,

    input wire predict_valid,
    input wire [6:0] predict_pc,
    output wire predict_taken,
    output wire [6:0] predict_history,

    input wire train_valid,
    input wire train_taken,
    input wire train_mispredicted,
    input wire [6:0] train_history,
    input wire [6:0] train_pc
);
wire [6:0] pht_index;
    wire [6:0] pht_history;
    wire [1:0] pht_value;
    wire [1:0] pht_next_value;
    wire [6:0] pht_next_history;

    assign pht_index = predict_pc ^ predict_history;
    assign pht_history = predict_history;
    assign predict_taken = pht_value[1];

    assign pht_next_value = pht_value + {~pht_value[1], pht_value[0]};
    assign pht_next_history = pht_history[5:0] | {~pht_history[6], pht_history[6]};

    reg [1:0] pht[127:0];
    reg [6:0] history;

    always @(posedge clk) begin
        if (train_valid) begin
            pht[train_pc] <= pht_next_value;
            if (train_mispredicted) begin
                history <= pht_next_history;
            end
        end
        if (predict_valid) begin
            history <= pht_next_history;
        end
    end

    assign pht_value = pht[pht_index];

endmodule

