      4'b0100: begin
        next_state = 4'b0000;
        next_counter = 4'b0100;
        next_shift_ena = 1'b0;
      end
      default: begin
        next_state = 4'b0000;
        next_counter = 4'b0000;
        next_shift_ena = 1'b0;
      end
    endcase
  end
  always @(posedge clk or posedge reset) begin
    if (reset) begin
      next_state <= 4'b0000;
      next_counter <= 4'b0000;
      next_shift_ena <= 1'b1;
    end
  end
