  input load,
  input [511:0] data,
  output reg [511:0] q
);
always @(posedge clk) begin
    if (load) begin
      q <= data;
    end else begin
      q[0] <= 0;
      q[511] <= 0;
      q[1:510] <= q[0:509] ^ q[2:511];
    end
  end
endmodule

module TopModule (
