  output out
);
wire A;
  wire B;

  assign out = A;

  assign A = ~B & ~in;
  assign B = ~A & in | areset;

endmodule

module TopModule (
  input clk,
  input j,
  input k,
  input areset,
  output out
);
wire [1:0] state;
  wire [1:0] next_state;

  assign out = state[0];

  assign next_state = state[1] ? (k ? 2'b00 : 2'b01) : (j ? 2'b01 : 2'b00);

  always @(posedge clk or posedge areset) begin
    if (areset) begin
      state <= 2'b00;
    end else begin
      state <= next_state;
    end
  end

endmodule

module TopModule (
