    if (load) begin
      q <= data;
    end else if (ena) begin
      case (amount)
        2'b00: q <= q << 1;
        2'b01: q <= q << 8;
        2'b10: q <= q >> 1;
        2'b11: q <= q >> 8;
      endcase
    end
  end
endmodule

module TopModule (
  input clk,
  input areset,
  input predict_valid,
  input predict_taken,
  output logic [31:0] predict_history,

  input train_mispredicted,
  input train_taken,
  input [31:0] train_history
);
logic [31:0] history;

  always_ff @(posedge clk) begin
    if (areset) begin
      history <= 0;
    end else if (predict_valid) begin
      history <= {history[30:0], predict_taken};
    end else if (train_mispredicted) begin
      history <= {train_history[30:0], train_taken};
    end
  end

  assign predict_history = history;

endmodule

module TopModule (
  input clk,
  input in,
  input areset,
  output out
);
reg state;
  reg next_state;

  always @(posedge clk) begin
    if (areset) begin
      state <= 1'b0;
    end else begin
      state <= next_state;
    end
  end

  always @(*) begin
    case (state)
      1'b0: begin
        if (in == 1'b0) begin
          next_state = 1'b0;
        end else begin
          next_state = 1'b1;
        end
      end
      1'b1: begin
        if (in == 1'b0) begin
          next_state = 1'b1;
        end else begin
          next_state = 1'b0;
        end
      end
      default: begin
        next_state = 1'b0;
      end
